/* Original exam-style quantum teaching; quantitative extensions are labelled in lessons. */
(function(){'use strict';const C=window.PhysicsScenarioCourse,H=C.helpers,{esc,paper,reveal,svg,text,line,arrow,number,check}=H;const P=s=>'<p>'+esc(s)+'</p>';const box=(x,y,w,h)=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" fill="#e6f0f5" stroke="#274858"/>';
function fig(k){let z='',title=k;const t=(x,y,s)=>text(x,y,s);const level=(y,s)=>line(180,y,600,y)+t(185,y-15,s);
const levels={levels:['−2 eV', '−5 eV','Emission: gap = 3 eV'],absorption:['5 eV','0 eV','Ground-state absorption: 0 → 5 eV'],cascade:['5 eV','0 eV','Cascade: 5 → 2 → 0 eV'],fluor:['4 eV excitation','0 eV ground','Relax to 2.5 eV; emit 2.5 eV'],metastable:['excited state','ground state','Long-lived intermediate stores excitation'],laserlevels:['3.20 eV upper','1.20 eV lower','Laser photon gap = 2.00 eV'],xraylevels:['−10 keV outer','−70 keV inner','Vacancy filled: photon gap = 60 keV'],pvbands:['conduction band','valence band','Photon excites electron; hole remains'],ledbands:['conduction band','valence band','Electron–hole recombination emits photon']};
if(levels[k]){const a=levels[k];z=level(110,a[0])+level(340,a[1])+arrow(400,120,400,325,'#aa501c')+t(440,230,'radiative transition');if(['cascade','fluor','metastable'].includes(k)){z=level(95,a[0])+level(220,k==='cascade'?'2 eV intermediate':k==='fluor'?'2.5 eV emitting state':'metastable state')+level(355,a[1])+arrow(280,345,280,110,'#246fb0')+t(55,260,'absorption')+arrow(450,108,450,210,'#9d6023')+t(475,165,k==='cascade'?'3 eV photon':'relaxation')+arrow(390,235,390,340,'#0c8076')+t(425,305,k==='cascade'?'2 eV photon':'emitted photon');}if(k==='absorption'||k==='pvbands')z=level(110,a[0])+level(340,a[1])+arrow(350,325,350,125,'#246fb0')+t(385,230,'absorbed photon');z+=t(65,410,a[2]);title='Energy-state model';}
else if(['em','photon','momentum','matter'].includes(k)){title=k==='em'?'Electromagnetic wave: transverse fields':k==='matter'?'Electron diffraction: matter-wave evidence':'Photon energy and momentum';z=arrow(100,235,650,235)+t(445,270,'propagation direction');if(k==='em'){z+=arrow(350,235,350,90,'#246fb0')+arrow(350,235,240,320,'#c26b20')+t(360,100,'electric field E')+t(80,350,'magnetic field B')+t(65,410,'E, B and propagation are mutually perpendicular.');}else z+=box(170,140,200,70)+t(185,180,k==='matter'?'electron: p = mv':k==='momentum'?'photon: p = h/λ':'photon: E = hf')+t(120,340,k==='matter'?'λ = h/p; do not use photon E = pc for electrons.':k==='momentum'?'Momentum transfer is possible even though photon rest mass is zero.':'Energy E = hc/λ; increasing photon count increases beam power.');}
else if(['peapparatus','xraytube','ledcircuit','lasercavity'].includes(k)){title='Labelled apparatus';if(k==='lasercavity')z=box(260,170,230,95)+line(190,110,190,325)+line(550,110,550,325)+t(275,210,'gain medium')+arrow(375,80,375,160,'#c16a21')+t(390,90,'pump energy')+arrow(200,285,540,285)+arrow(545,205,685,205)+t(565,165,'output')+t(65,375,'mirror')+t(470,375,'partly transmitting mirror');else if(k==='ledcircuit')z=box(85,170,130,90)+t(100,210,'supply Vs')+line(215,190,290,190)+box(290,165,130,50)+t(315,200,'R')+line(420,190,475,190)+box(475,165,160,70)+t(490,205,'LED drop Vf')+line(635,190,685,190)+line(685,190,685,325)+line(685,325,150,325)+line(150,325,150,260)+arrow(250,120,400,120)+t(285,95,'current I →')+t(80,395,'Vs = IR + Vf; anode toward positive supply.');else z=box(140,140,70,200)+box(550,140,70,200)+arrow(230,230,530,230)+t(105,115,k==='xraytube'?'heated cathode':'photoemissive surface')+t(525,115,k==='xraytube'?'target anode':'collector')+arrow(350,70,200,150,'#c16a21')+t(350,65,k==='xraytube'?'electron energy eV':'incident photons hf')+t(230,300,k==='xraytube'?'accelerated electrons →':'photoelectrons →')+t(80,405,k==='xraytube'?'Target heating + X-rays; voltage sets maximum photon energy.':'Retarding potential stops fastest electrons: Kmax = eVs.');}
else if(['slits','fringes','singleparticle'].includes(k)){title='Double-slit evidence';z=line(280,90,280,170)+line(280,195,280,260)+line(280,285,280,390)+line(620,90,620,390)+t(205,65,'two slits')+t(555,65,'screen')+arrow(80,240,255,240)+line(285,180,615,150,'#246fb0')+line(285,275,615,150,'#c16a21')+t(335,115,'two path lengths')+t(75,415,k==='singleparticle'?'Localised hits accumulate into an interference pattern.':k==='fringes'?'Bright: path difference mλ. Dark: (m + ½)λ.':'Coherent alternatives overlap at the screen.');for(let i=0;i<7;i++)z+=box(625,120+i*38,k==='singleparticle'?8:35,12);}
else if(k.startsWith('polar')){title='Polariser transmission axes';const angles=k==='polarthree'?[0,45,90]:k==='polartwo'?[0,90]:[0];angles.forEach((a,i)=>{const x=200+i*180;z+=box(x,135,80,190)+line(x+40-60*Math.sin(a*Math.PI/180),230-75*Math.cos(a*Math.PI/180),x+40+60*Math.sin(a*Math.PI/180),230+75*Math.cos(a*Math.PI/180),'#246fb0')+t(x-5,365,a+'° axis');});z+=arrow(65,90,680,90)+t(65,415,k==='polarthree'?'Supplied Malus extension: successive relative angles are 45° and 45°.':k==='polartwo'?'Crossed ideal axes transmit no already polarised component.':'One ideal filter: unpolarised light gives Iout = Iin/2.');}
else if(['pebalance','threshold','stimulated','pvenergy','thermalpower','ledcolour'].includes(k)){title='Energy accounting';const ss=k==='pebalance'?['photon hf','escape energy φ','maximum K = hf − φ']:k==='threshold'?['hf < φ: no emission','hf = φ: threshold','hf > φ: kinetic energy']:k==='stimulated'?['excited particle + trigger','lower particle + 2 photons','medium supplies added hf']:k==='pvenergy'?['input GA','electrical output ηGA','other transfers (1 − η)GA']:k==='ledcolour'?['450 nm: larger E','650 nm: smaller E','both travel at c in vacuum']:['emitted power','received power','net = emitted − received'];ss.forEach((s,i)=>{z+=box(105,90+i*105,550,70)+t(130,132+i*105,s);});}
else{title='Graph model: '+k;z=arrow(100,360,650,360)+arrow(100,360,100,80);let xlabel='',ylabel='',path='',cap='';if(k==='plankgraph'||k==='uncertainty'){xlabel='frequency f / (10¹⁴ Hz)';ylabel='Vs (V)';path='M 280 360 L 590 130';cap='Scaled slope = 0.414375 V per unit; h = e × slope/10¹⁴.';if(k==='uncertainty')z+=line(280,360,590,100,'#c16a21')+line(280,360,590,160,'#0c8076');}else if(k==='pvcurve'){xlabel='terminal voltage V';ylabel='current I';path='M 100 125 Q 450 125 590 360';cap='Open circuit: I = 0. Short circuit: V ≈ 0. Use paired IV.';}else if(k==='xrayspectrum'){xlabel='wavelength λ';ylabel='spectral output';path='M 190 360 Q 290 85 390 230 Q 510 325 630 340';cap='Cut-off on short-wavelength side; peaks depend on target.';z+=line(190,345,190,290,'#c16a21')+t(135,280,'λmin')+line(370,240,370,95,'#246fb0')+t(390,105,'characteristic line');}else{xlabel='wavelength λ';ylabel='spectral density';path='M 110 355 C 140 355 175 110 260 150 S 440 300 630 340';cap=k==='thermalpeak'?'Hotter spectrum peaks at shorter wavelength.': 'Schematic wavelength spectrum; area represents total emission.';if(k==='thermalcurves')z+='<path d="M110 355 C200 355 265 220 350 240 S500 330 630 350" fill="none" stroke="#c16a21" stroke-width="3"/>'+t(380,190,'cooler curve');}z+='<path d="'+path+'" fill="none" stroke="#246fb0" stroke-width="4"/>'+t(420,390,xlabel)+t(110,65,ylabel)+t(65,440,cap);}
return svg(title,z,480);}

{const s={"id": "quantum-focus-1", "parent": "quantum", "title": "Photons: waves, energy packets and momentum", "shortTitle": "Photons: waves, energy packets and momentum", "subtitle": "Connect electromagnetic fields to photons, then solve wavelength, frequency, energy, momentum and photon-count scenarios.", "bank": [{"q": "In a vacuum electromagnetic wave, E and B fields are\u2026", "o": ["parallel to each other", "perpendicular to each other and travel direction", "longitudinal only"], "a": 1, "explain": "Both field oscillations are transverse and mutually perpendicular."}, {"q": "Changing 600 nm to 300 nm changes photon energy by\u2026", "o": ["half", "twice", "no change"], "a": 1, "explain": "E = hc/\u03bb."}, {"q": "Convert 2.00 eV to joules.", "o": ["3.20 \u00d7 10\u207b\u00b9\u2079 J", "1.25 \u00d7 10\u00b9\u2079 J", "2.00 J"], "a": 0, "explain": "Multiply by 1.60 \u00d7 10\u207b\u00b9\u2079 J/eV."}, {"q": "A brighter monochromatic beam at fixed f has\u2026", "o": ["larger hf", "more photons per second per area", "faster photons"], "a": 1, "explain": "Intensity increases through photon flux."}, {"q": "Photon momentum is\u2026", "o": ["h/\u03bb", "mc using electron mass", "zero"], "a": 0, "explain": "p = E/c = h/\u03bb."}, {"q": "Light can propagate through a vacuum because\u2026", "o": ["air vibrations reach everywhere", "oscillating fields do not require a material medium", "its frequency is zero"], "a": 1, "explain": "Electromagnetic waves are not mechanical waves."}], "practice": [{"q": "A 660 nm beam has power 3.00 mW. Find photon energy in J and photon rate.", "points": ["\u03bb = 6.60 \u00d7 10\u207b\u2077 m; E = hc/\u03bb = 3.01 \u00d7 10\u207b\u00b9\u2079 J.", "N\u0307 = 0.00300/E = 9.95 \u00d7 10\u00b9\u2075 photons/s.", "Increasing power at fixed wavelength increases rate, not E per photon."]}, {"q": "A photon has momentum 2.21 \u00d7 10\u207b\u00b2\u2077 kg m/s. Find wavelength and energy in eV.", "points": ["\u03bb = h/p = 3.00 \u00d7 10\u207b\u2077 m = 300 nm.", "E = pc = 6.63 \u00d7 10\u207b\u00b9\u2079 J = 4.14 eV.", "Use photon relationships, not non-relativistic p = mv."]}], "pages": [{"title": "Light carries energy across empty space", "html": "<div class=\"pp-page\"><p>Light does not need air, water or a material rope. Its electric and magnetic fields can propagate through a vacuum, where speed c = 3.00 \u00d7 10\u2078 m/s.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Three perpendicular directions", "html": "<div class=\"pp-page\"><p>The electric field, magnetic field and direction of travel are mutually perpendicular. A diagram of a field wave is a graph of field strength; it does not mean a photon follows a wavy physical path.</p></div>", "chapter": 0, "type": "learn"}, {"title": "An oscillating charge is a source", "html": "<div class=\"pp-page\"><p>An accelerating or oscillating charge produces electromagnetic radiation. The emitted wave frequency follows the charge oscillation frequency; an incident wave can make other charges oscillate.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Frequency counts cycles", "html": "<div class=\"pp-page\"><p>Frequency f is the number of oscillations per second, measured in hertz. It describes how fast a field changes at one location, rather than the speed at which light travels.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Wavelength measures spatial repetition", "html": "<div class=\"pp-page\"><p>Wavelength \u03bb is the distance between equal-phase positions, such as neighbouring field maxima. Convert nanometres using 1 nm = 10\u207b\u2079 m before using SI equations.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Connect wavelength and frequency", "html": "<div class=\"pp-page\"><p>For light in vacuum, c = f\u03bb, so f = c/\u03bb. Shorter wavelength means larger frequency because c stays fixed; it does not mean vacuum light moves faster.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A photon is one energy packet", "html": "<div class=\"pp-page\"><p>Emission and absorption of light occur in discrete packets called photons. The photon model describes interactions; the wave model remains useful for interference and diffraction.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Planck sets the energy scale", "html": "<div class=\"pp-page\"><p>One photon has E = hf, with h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s in these examples. Multiplying joule seconds by inverse seconds leaves joules.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Use wavelength directly for energy", "html": "<div class=\"pp-page\"><p>Combining E = hf and c = f\u03bb gives E = hc/\u03bb. This avoids an unnecessary rounded intermediate frequency when wavelength is supplied.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Electronvolts are energy units", "html": "<div class=\"pp-page\"><p>One electronvolt is 1.60 \u00d7 10\u207b\u00b9\u2079 J. Divide joules by this conversion to obtain eV; the term electronvolt does not mean photon energy is a voltage.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Reverse the energy calculation", "html": "<div class=\"pp-page\"><p>If E is given in eV, multiply by 1.60 \u00d7 10\u207b\u00b9\u2079 to obtain joules, then use \u03bb = hc/E. Keep powers of ten explicit to avoid producing a metre-sized visible wavelength.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Photons carry momentum", "html": "<div class=\"pp-page\"><p>For a photon E = pc, hence p = E/c = h/\u03bb. The photon has zero rest mass, so the non-relativistic formula p = mv is not the way to calculate photon momentum.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Brightness is not energy per photon", "html": "<div class=\"pp-page\"><p>For monochromatic light, greater intensity at fixed frequency means more photons arriving each second per unit area. Individual photon energy remains hf.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Power gives the photon arrival rate", "html": "<div class=\"pp-page\"><p>If all beam power P is carried by photons of energy E, rate N\u0307 = P/E. Power is joules per second, so dividing by joules produces photons per second.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A pulse has finite total energy", "html": "<div class=\"pp-page\"><p>For constant power acting for time t, pulse energy is Pt. The number of photons in that pulse is N = Pt/E, which differs from the photon rate P/E.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Compare colours using ratios", "html": "<div class=\"pp-page\"><p>For two vacuum wavelengths, E\u2081/E\u2082 = \u03bb\u2082/\u03bb\u2081. Halving wavelength doubles photon energy and momentum without changing the vacuum propagation speed.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Vacuum formulas need a stated context", "html": "<div class=\"pp-page\"><p>In a material, frequency stays fixed at a stationary boundary while wave speed and wavelength change. Use vacuum wavelength in hc/\u03bb with c, or use the frequency directly for energy.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Choose a model for the evidence", "html": "<div class=\"pp-page\"><p>Interference requires a wave description; energy transfer in individual absorption events requires photons. A strong explanation names the observation first and then the model that explains it.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Green photon: from nm to frequency", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Find frequency and energy of vacuum light with \u03bb = 500 nm.</p><ol><li>Write \u03bb = 500 \u00d7 10\u207b\u2079 = 5.00 \u00d7 10\u207b\u2077 m. The known wavelength fixes f through c = f\u03bb.</li><li>f = 3.00 \u00d7 10\u2078/(5.00 \u00d7 10\u207b\u2077) = 6.00 \u00d7 10\u00b9\u2074 Hz.</li><li>E = hf = 6.63 \u00d7 10\u207b\u00b3\u2074 \u00d7 6.00 \u00d7 10\u00b9\u2074 = 3.978 \u00d7 10\u207b\u00b9\u2079 J = 2.49 eV. This is one photon, not the whole beam.</li></ol>__FIG_em__</div>", "chapter": 2, "type": "worked"}, {"title": "Ultraviolet photon: energy directly", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Find energy in J and eV at \u03bb = 250 nm.</p><ol><li>Convert to 2.50 \u00d7 10\u207b\u2077 m. Choose E = hc/\u03bb to avoid rounding f.</li><li>E = (6.63 \u00d7 10\u207b\u00b3\u2074)(3.00 \u00d7 10\u2078)/(2.50 \u00d7 10\u207b\u2077) = 7.956 \u00d7 10\u207b\u00b9\u2079 J.</li><li>Divide by 1.60 \u00d7 10\u207b\u00b9\u2079 J/eV: E = 4.97 eV. Compared with 500 nm, half the wavelength gives twice the energy.</li></ol>__FIG_photon__</div>", "chapter": 2, "type": "worked"}, {"title": "Reverse scenario: energy determines colour", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A photon has energy 3.00 eV. Find vacuum wavelength.</p><ol><li>Convert E = 3.00 \u00d7 1.60 \u00d7 10\u207b\u00b9\u2079 = 4.80 \u00d7 10\u207b\u00b9\u2079 J.</li><li>Rearrange E = hc/\u03bb to \u03bb = hc/E.</li><li>\u03bb = 1.989 \u00d7 10\u207b\u00b2\u2075/(4.80 \u00d7 10\u207b\u00b9\u2079) = 4.14 \u00d7 10\u207b\u2077 m = 414 nm. The answer lies in the visible/violet region.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Momentum without rest mass", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Calculate momentum of a 600 nm photon.</p><ol><li>Convert 600 nm to 6.00 \u00d7 10\u207b\u2077 m; use p = h/\u03bb.</li><li>p = 6.63 \u00d7 10\u207b\u00b3\u2074/(6.00 \u00d7 10\u207b\u2077) = 1.105 \u00d7 10\u207b\u00b2\u2077 kg m/s.</li><li>Check E = pc = 3.315 \u00d7 10\u207b\u00b9\u2079 J, agreeing with hc/\u03bb. Zero rest mass does not imply zero momentum.</li></ol>__FIG_momentum__</div>", "chapter": 2, "type": "worked"}, {"title": "Beam scenario: rate and total number", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A monochromatic 500 nm beam has power 2.00 mW for 0.100 s. Find photon rate and pulse count.</p><ol><li>P = 2.00 \u00d7 10\u207b\u00b3 W; one photon has E = 3.978 \u00d7 10\u207b\u00b9\u2079 J.</li><li>N\u0307 = P/E = 5.03 \u00d7 10\u00b9\u2075 photons/s.</li><li>N = N\u0307t = 5.03 \u00d7 10\u00b9\u2074 photons. Check that NE = Pt = 2.00 \u00d7 10\u207b\u2074 J.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Two beams: energy and brightness are separate", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Equal-power 400 nm and 800 nm beams are compared. Which has more photons per second?</p><ol><li>Energy is inversely proportional to wavelength, so E\u2084\u2080\u2080 = 2E\u2088\u2080\u2080.</li><li>At fixed power N\u0307 = P/E, so the 800 nm beam has twice as many photons per second.</li><li>Both travel at c in vacuum. Equal beam power does not mean equal photon energy or equal photon count.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Energy of one 400 nm photon in eV", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Frequency of vacuum 750 nm light, in units of 10\u00b9\u2074 Hz", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: em", "html": "<div class=\"pp-page\">__FIG_em__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: photon", "html": "<div class=\"pp-page\">__FIG_photon__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: momentum", "html": "<div class=\"pp-page\">__FIG_momentum__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Why can a bright red beam fail to eject electrons while a dim ultraviolet beam succeeds?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Why can a bright red beam fail to eject electrons while a dim ultraviolet beam succeeds?", "points": ["Photon energy depends on frequency, while brightness determines how many photons arrive. The next lesson compares individual photon energy with a surface threshold."], "claim": "Connect electromagnetic fields to photons, then solve wavelength, frequency, energy, momentum and photon-count scenarios."}, "summary": "Connect electromagnetic fields to photons, then solve wavelength, frequency, energy, momentum and photon-count scenarios."};const guides=[["Energy of one 400 nm photon in eV", 3.1078125, "eV", "E = hc/\u03bb = 4.9725 \u00d7 10\u207b\u00b9\u2079 J; divide by 1.60 \u00d7 10\u207b\u00b9\u2079."], ["Frequency of vacuum 750 nm light, in units of 10\u00b9\u2074 Hz", 4, "\u00d7 10\u00b9\u2074 Hz", "f = 3.00 \u00d7 10\u2078/(750 \u00d7 10\u207b\u2079) = 4.00 \u00d7 10\u00b9\u2074 Hz."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("Photon energy depends on frequency, while brightness determines how many photons arrive. The next lesson compares individual photon energy with a surface threshold.")));});C.register(s);}

{const s={"id": "quantum-focus-2", "parent": "quantum", "title": "Photoelectric effect: thresholds, current and stopping potential", "shortTitle": "Photoelectric effect: thresholds, current and stopping potential", "subtitle": "Separate intensity from frequency, handle no-emission cases, and connect photon energy to electron kinetic energy and stopping potential.", "bank": [{"q": "A calculated hf \u2212 \u03c6 < 0 means\u2026", "o": ["electrons travel backwards", "no single-photon photoemission", "negative-mass electrons"], "a": 1, "explain": "The photon cannot pay the escape energy."}, {"q": "Increasing intensity at fixed above-threshold f changes\u2026", "o": ["maximum kinetic energy", "photon arrival rate", "work function"], "a": 1, "explain": "More photons arrive; energy per photon stays hf."}, {"q": "The stopping relation is\u2026", "o": ["Kmax = eVs", "Kmax = hf + \u03c6", "Vs = hf"], "a": 0, "explain": "eVs has energy units."}, {"q": "For emission, vacuum wavelength must be\u2026", "o": ["at least \u03bb\u2080", "no longer than \u03bb\u2080", "irrelevant"], "a": 1, "explain": "Shorter wavelengths have higher photon energy."}, {"q": "Kmax against frequency has slope\u2026", "o": ["\u03c6", "h", "c"], "a": 1, "explain": "Kmax = hf \u2212 \u03c6."}, {"q": "At fixed f, a smaller \u03c6 gives\u2026", "o": ["larger Kmax", "smaller Kmax", "higher threshold f"], "a": 0, "explain": "Less energy is used to escape."}], "practice": [{"q": "A 300 nm beam strikes a surface with \u03c6 = 2.20 eV. Find Kmax in J and stopping potential.", "points": ["E = hc/\u03bb = 6.63 \u00d7 10\u207b\u00b9\u2079 J = 4.14375 eV.", "Kmax = (4.14375 \u2212 2.20) eV = 3.11 \u00d7 10\u207b\u00b9\u2079 J.", "Vs = 1.94 V, as a retarding magnitude."]}, {"q": "A surface has \u03c6 = 3.00 eV. Compare 500 nm and 350 nm illumination; then double intensity of each.", "points": ["500 nm gives 2.49 eV < \u03c6: no emission.", "350 nm gives 3.55 eV > \u03c6: Kmax \u2248 0.552 eV.", "Intensity cannot create ordinary single-photon emission at 500 nm; at 350 nm it increases current but not Kmax."]}], "pages": [{"title": "Begin with the physical event", "html": "<div class=\"pp-page\"><p>In the photoelectric effect, light incident on a surface can eject electrons. The incident object is a photon, the escaping object is an electron, and their energies must not be confused.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A surface requires an escape energy", "html": "<div class=\"pp-page\"><p>The work function \u03c6 is the minimum energy needed to remove an electron from the surface. Different materials and surface conditions can have different work functions.</p></div>", "chapter": 0, "type": "learn"}, {"title": "One-photon energy accounting", "html": "<div class=\"pp-page\"><p>In the standard single-photon model, one photon transfers hf to one electron. The most energetic escaping electron has Kmax = hf \u2212 \u03c6; the surface binding energy is paid first.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Negative arithmetic means no emission", "html": "<div class=\"pp-page\"><p>If hf < \u03c6, the equation would give a negative kinetic energy. This is not a real emitted electron moving backwards: no photoelectron is emitted by this model.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Threshold is a minimum frequency", "html": "<div class=\"pp-page\"><p>At threshold Kmax = 0, so hf\u2080 = \u03c6 and f\u2080 = \u03c6/h. A photon just at threshold has only enough energy to release an electron with limiting zero kinetic energy.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Threshold wavelength is a maximum wavelength", "html": "<div class=\"pp-page\"><p>\u03bb\u2080 = hc/\u03c6 in vacuum. Wavelengths shorter than \u03bb\u2080 have sufficient photon energy; wavelengths longer than \u03bb\u2080 do not, reversing the frequency inequality.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Intensity changes photon arrivals", "html": "<div class=\"pp-page\"><p>At fixed frequency above threshold, larger intensity means more incoming photons per second. If collection and quantum yield stay comparable, photoelectric current increases.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Frequency changes electron energy", "html": "<div class=\"pp-page\"><p>At fixed surface, increasing f increases hf \u2212 \u03c6. Maximum kinetic energy rises; the effect on current depends on photon flux and collection, so do not claim current must rise.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Brightness cannot rescue a subthreshold photon", "html": "<div class=\"pp-page\"><p>In the normal single-photon regime, a brighter beam below f\u2080 still gives insufficient energy per photon. Special multiphoton processes at extreme intensities are outside this introductory model.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Electrons emerge with a range of energies", "html": "<div class=\"pp-page\"><p>The equation gives a maximum, not the kinetic energy of every photoelectron. Electrons deeper in the material can lose energy before reaching the surface.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Collecting current counts electrons", "html": "<div class=\"pp-page\"><p>Photoelectric current I is charge per second. If all emitted electrons are collected, I/e gives electrons per second; it is not automatically equal to incident photon rate.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A retarding field tests kinetic energy", "html": "<div class=\"pp-page\"><p>The collector can be made negative relative to the emitting surface, opposing electron motion. Electrons need kinetic energy to cross this electric potential energy barrier.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Stopping potential stops the fastest electrons", "html": "<div class=\"pp-page\"><p>Stopping-potential magnitude Vs satisfies eVs = Kmax. At this retarding magnitude even the fastest photoelectrons fail to reach the collector, so measured photocurrent falls to zero.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Use signs and magnitudes clearly", "html": "<div class=\"pp-page\"><p>An electron has charge \u2212e, but Vs is commonly reported as the positive magnitude of the retarding potential. State the voltage convention rather than inserting a negative kinetic energy.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Electronvolts simplify a voltage step", "html": "<div class=\"pp-page\"><p>If Kmax = 1.20 eV, then Vs = 1.20 V because one electron crossing one volt changes energy by one eV. This shortcut works for a single electron charge magnitude e.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Read the energy\u2013frequency graph", "html": "<div class=\"pp-page\"><p>Kmax versus f is a straight line above threshold: slope h, vertical intercept \u2212\u03c6 and horizontal intercept f\u2080. The negative extrapolated intercept is not a physical negative electron energy.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Surface changes move the intercept", "html": "<div class=\"pp-page\"><p>For two surfaces under the same light, the smaller work function gives larger Kmax and lower f\u2080. Their Kmax\u2013f slopes are the same Planck constant h.</p></div>", "chapter": 1, "type": "learn"}, {"title": "State the experimental controls", "html": "<div class=\"pp-page\"><p>To compare intensity effects, keep frequency and surface fixed; to compare frequency effects, control intensity or photon flux and describe which is held fixed. Contact potentials and background current can shift measured results.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Above threshold: calculate electron energy", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Light at f = 8.00 \u00d7 10\u00b9\u2074 Hz strikes \u03c6 = 2.00 eV. Find Kmax and Vs.</p><ol><li>Convert \u03c6 = 3.20 \u00d7 10\u207b\u00b9\u2079 J; photon energy hf = 5.304 \u00d7 10\u207b\u00b9\u2079 J.</li><li>Kmax = 2.104 \u00d7 10\u207b\u00b9\u2079 J = 1.315 eV.</li><li>Vs = Kmax/e = 1.315 V \u2248 1.32 V. The collector must retard electrons, not accelerate them.</li></ol>__FIG_pebalance__</div>", "chapter": 2, "type": "worked"}, {"title": "Below threshold: reject an impossible result", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A \u03c6 = 2.00 eV surface receives 700 nm light. Is there photoemission?</p><ol><li>E = hc/\u03bb = 2.841 \u00d7 10\u207b\u00b9\u2079 J = 1.776 eV.</li><li>E < \u03c6, so the standard single-photon model predicts no photoelectrons.</li><li>Do not report K = \u22120.224 eV or a negative stopping potential; there is no emitted-electron energy distribution to stop.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Threshold: frequency and wavelength", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Find f\u2080 and \u03bb\u2080 for \u03c6 = 2.50 eV.</p><ol><li>\u03c6 = 4.00 \u00d7 10\u207b\u00b9\u2079 J. At threshold hf\u2080 = \u03c6.</li><li>f\u2080 = 4.00 \u00d7 10\u207b\u00b9\u2079/(6.63 \u00d7 10\u207b\u00b3\u2074) = 6.03 \u00d7 10\u00b9\u2074 Hz.</li><li>\u03bb\u2080 = c/f\u2080 = 4.97 \u00d7 10\u207b\u2077 m = 497 nm. Emission requires \u03bb \u2264 \u03bb\u2080 in the ideal model.</li></ol>__FIG_threshold__</div>", "chapter": 2, "type": "worked"}, {"title": "Reverse scenario: infer work function", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> At 400 nm the stopping potential is 1.10 V. Find \u03c6 in eV.</p><ol><li>Photon energy is hc/\u03bb = 3.1078 eV. The maximum kinetic energy is eVs = 1.10 eV.</li><li>Rearrange \u03c6 = E \u2212 Kmax = 3.1078 \u2212 1.10 = 2.0078 eV.</li><li>\u03c6 \u2248 2.01 eV. It must be less than this incident photon energy because emission occurs.</li></ol>__FIG_peapparatus__</div>", "chapter": 2, "type": "worked"}, {"title": "Intensity scenario: same stopping point", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Above threshold, a beam gives saturation current 2.00 \u03bcA and Vs = 0.800 V. Intensity doubles at fixed f. Predict changes under equal collection efficiency.</p><ol><li>Photon arrival rate doubles, so emitted-electron rate and saturation current approximately double to 4.00 \u03bcA.</li><li>Frequency and \u03c6 are unchanged, so Kmax and Vs remain 0.800 eV and 0.800 V.</li><li>This prediction assumes the emission yield and collection conditions remain unchanged. It does not require each photon to eject an electron.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Electron count: current is a rate", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A collected photoelectric current is 3.20 \u03bcA. Find electron rate and number collected in 0.500 s.</p><ol><li>I = 3.20 \u00d7 10\u207b\u2076 C/s; electron rate = I/e.</li><li>N\u0307 = 3.20 \u00d7 10\u207b\u2076/(1.60 \u00d7 10\u207b\u00b9\u2079) = 2.00 \u00d7 10\u00b9\u00b3 electrons/s.</li><li>N = N\u0307t = 1.00 \u00d7 10\u00b9\u00b3 electrons. No photon wavelength is needed for this charge-count question.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Stopping potential for Kmax = 2.40 eV", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Maximum electron energy when hf = 5.00 eV and \u03c6 = 3.20 eV", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: peapparatus", "html": "<div class=\"pp-page\">__FIG_peapparatus__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: pebalance", "html": "<div class=\"pp-page\">__FIG_pebalance__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: threshold", "html": "<div class=\"pp-page\">__FIG_threshold__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>A student says brighter light must eject faster electrons. What condition makes that claim fail?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "A student says brighter light must eject faster electrons. What condition makes that claim fail?", "points": ["At fixed frequency and surface, each photon has the same hf and the same work function is paid. Greater intensity changes emission rate, while maximum kinetic energy remains hf \u2212 \u03c6."], "claim": "Separate intensity from frequency, handle no-emission cases, and connect photon energy to electron kinetic energy and stopping potential."}, "summary": "Separate intensity from frequency, handle no-emission cases, and connect photon energy to electron kinetic energy and stopping potential."};const guides=[["Stopping potential for Kmax = 2.40 eV", 2.4, "V", "For an electron eVs = Kmax, so 2.40 eV corresponds to 2.40 V."], ["Maximum electron energy when hf = 5.00 eV and \u03c6 = 3.20 eV", 1.8, "eV", "Kmax = 5.00 \u2212 3.20 = 1.80 eV; the work function is subtracted once."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("At fixed frequency and surface, each photon has the same hf and the same work function is paid. Greater intensity changes emission rate, while maximum kinetic energy remains hf \u2212 \u03c6.")));});C.register(s);}

{const s={"id": "quantum-focus-3", "parent": "quantum", "title": "Atoms and matter waves: spectra, transitions and de Broglie evidence", "shortTitle": "Atoms and matter waves: spectra, transitions and de Broglie evidence", "subtitle": "Read discrete energy levels, distinguish emission from absorption, and calculate matter wavelengths without applying photon equations to electrons.", "bank": [{"q": "Downward atomic transition means\u2026", "o": ["absorption", "emission", "no energy change"], "a": 1, "explain": "The atom loses energy and emits a photon."}, {"q": "From \u22121 to \u22124 eV, photon energy is\u2026", "o": ["\u22123 eV", "3 eV", "5 eV"], "a": 1, "explain": "Ei \u2212 Ef = 3 eV."}, {"q": "Two cascade photon energies\u2026", "o": ["sum to the total gap", "always equal each other", "give wavelengths that add"], "a": 0, "explain": "Energy is conserved across both transitions."}, {"q": "Matter wavelength is\u2026", "o": ["h/p", "pc", "hf only"], "a": 0, "explain": "The de Broglie relation connects matter wavelength and momentum."}, {"q": "For low-speed electron kinetic energy use\u2026", "o": ["pc", "p\u00b2/(2m)", "zero"], "a": 1, "explain": "E = pc is a photon relation, not non-relativistic electron kinetic energy."}, {"q": "Quadrupling accelerating voltage changes low-energy electron \u03bb to\u2026", "o": ["one quarter", "one half", "twice"], "a": 1, "explain": "\u03bb \u221d 1/\u221aV."}], "practice": [{"q": "An atom has levels \u22126.00, \u22123.00 and \u22121.00 eV. Starting at \u22121.00 eV, list direct-to-ground and cascade photon energies.", "points": ["Direct transition emits 5.00 eV.", "Cascade emits 2.00 eV then 3.00 eV.", "The cascade total is 5.00 eV; the emitted wavelengths differ from the direct line."]}, {"q": "A non-relativistic electron has momentum 3.00 \u00d7 10\u207b\u00b2\u2074 kg m/s. Calculate wavelength and explain the effect of doubling momentum.", "points": ["\u03bb = h/p = 2.21 \u00d7 10\u207b\u00b9\u2070 m = 0.221 nm.", "Doubling momentum halves wavelength to 0.1105 nm.", "Photon E = pc must not be substituted for electron kinetic energy."]}], "pages": [{"title": "Atomic energy states are discrete", "html": "<div class=\"pp-page\"><p>An atom can occupy particular allowed internal energy states. It cannot remain in every arbitrary energy between those states, which is why its light spectrum contains separate lines.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Energy diagrams use a vertical energy axis", "html": "<div class=\"pp-page\"><p>A horizontal line represents one allowed state, not a circular orbit drawn to scale. Higher on the diagram means greater energy; the gap determines the photon energy.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Ground and excited states", "html": "<div class=\"pp-page\"><p>The ground state is the lowest allowed bound energy state. Excited states have higher energy; an atom may reach them by absorbing a photon or through another energy-transfer process.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Emission is a downward transition", "html": "<div class=\"pp-page\"><p>When an atom falls from Ei to Ef with Ei > Ef, it emits a photon of energy Ei \u2212 Ef. The photon energy is positive even when both bound-state values are negative.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Absorption is an upward transition", "html": "<div class=\"pp-page\"><p>A bound-bound absorption needs a photon energy matching an allowed gap from the atom\u2019s occupied state. A photon with an arbitrary non-matching energy is not partly absorbed to reach that discrete state.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Calculate the gap before the wavelength", "html": "<div class=\"pp-page\"><p>Use \u0394E = |Ef \u2212 Ei|, convert eV to J, then \u03bb = hc/\u0394E. Subtract levels first; do not calculate two wavelengths and then subtract them.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Negative bound energies have a reference", "html": "<div class=\"pp-page\"><p>A common convention takes a free electron at rest far from the atom as E = 0. Negative energies indicate bound states; they are not negative photon energies.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Ionisation reaches the continuum", "html": "<div class=\"pp-page\"><p>Removing an electron from a bound atom requires at least the energy from its state to E = 0. Above that threshold the excess can become kinetic energy of the freed electron.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A cascade uses several photons", "html": "<div class=\"pp-page\"><p>An excited atom can return through intermediate levels. Each drop emits its own photon, and the sum of photon energies equals the total energy lost by the atom.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Energy sums do not make wavelength sums", "html": "<div class=\"pp-page\"><p>For a cascade, E31 = E32 + E21, but \u03bb31 is not \u03bb32 + \u03bb21. Wavelength is inversely related to photon energy.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Emission lines identify elements", "html": "<div class=\"pp-page\"><p>Elements have distinct sets of allowed electronic energies, producing characteristic spectral lines. Several matching lines provide stronger identification than one coincidental wavelength.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Absorption lines need populated lower states", "html": "<div class=\"pp-page\"><p>Cool gas in front of a continuum source removes matching wavelengths for upward transitions from available lower states. Not every possible level pair must appear with equal strength.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Bohr is a useful limited model", "html": "<div class=\"pp-page\"><p>The Bohr model combines quantised states with photons and helps explain hydrogen\u2019s line spectrum. It is a simplified model, not a complete account of many-electron atoms or all quantum behaviour.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Matter can show wave behaviour", "html": "<div class=\"pp-page\"><p>Electron diffraction and single-electron interference show that particles also have wave-like properties. Localised detector events do not remove the wave pattern accumulated across many events.</p></div>", "chapter": 1, "type": "learn"}, {"title": "De Broglie connects wavelength and momentum", "html": "<div class=\"pp-page\"><p>For matter waves \u03bb = h/p. Larger momentum means shorter wavelength; this relation applies beyond light, but E = pc is only the photon energy relation here.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Low-speed electron momentum", "html": "<div class=\"pp-page\"><p>For a non-relativistic electron p = mv. If speed is supplied, calculate mv then \u03bb = h/(mv), using electron mass 9.11 \u00d7 10\u207b\u00b3\u00b9 kg.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Accelerating an electron gives kinetic energy", "html": "<div class=\"pp-page\"><p>For an electron accelerated from rest through magnitude V, K = eV. At low energy p = \u221a(2mK), giving \u03bb = h/\u221a(2meV); explicitly check the non-relativistic assumption.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Complementary models follow the experiment", "html": "<div class=\"pp-page\"><p>Use discrete energy transfer for spectra and wave interference for diffraction. Do not say an electron is a tiny classical wave of material moving through both slits; state what measured outcomes the models predict.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Emission: subtract negative levels", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> An atom drops from \u22122.00 eV to \u22125.00 eV. Find emitted wavelength.</p><ol><li>Energy lost is Ei \u2212 Ef = (\u22122.00) \u2212 (\u22125.00) = 3.00 eV.</li><li>Convert to 4.80 \u00d7 10\u207b\u00b9\u2079 J; \u03bb = 1.989 \u00d7 10\u207b\u00b2\u2075/(4.80 \u00d7 10\u207b\u00b9\u2079) = 414 nm.</li><li>The arrow points down on the energy diagram. Photon energy is positive.</li></ol>__FIG_levels__</div>", "chapter": 2, "type": "worked"}, {"title": "Absorption: test whether a photon matches", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Allowed levels are 0, 2.00 and 5.00 eV; atoms begin at 0. Would 3.00 eV light excite them to a bound state?</p><ol><li>Possible upward gaps from the occupied ground state are 2.00 and 5.00 eV.</li><li>A 3.00 eV photon matches neither ground-state gap, so no corresponding bound-bound absorption occurs in this ideal model.</li><li>The 3.00 eV gap between 2.00 and 5.00 eV would matter if the 2.00 eV state were populated.</li></ol>__FIG_absorption__</div>", "chapter": 2, "type": "worked"}, {"title": "Cascade: two photons, conserved total", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Levels are 0, 2.00 and 5.00 eV. Compare direct 5\u21920 emission with 5\u21922\u21920.</p><ol><li>Direct emission has 5.00 eV and \u03bb = 249 nm.</li><li>The cascade emits 3.00 eV (414 nm) and 2.00 eV (622 nm).</li><li>3.00 + 2.00 = 5.00 eV, conserving energy. 414 + 622 nm does not equal 249 nm.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Matter wave: speed is supplied", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> An electron travels at 2.00 \u00d7 10\u2076 m/s. Find de Broglie wavelength.</p><ol><li>This speed is 0.00667c, so p = mv is a suitable non-relativistic approximation.</li><li>p = (9.11 \u00d7 10\u207b\u00b3\u00b9)(2.00 \u00d7 10\u2076) = 1.822 \u00d7 10\u207b\u00b2\u2074 kg m/s.</li><li>\u03bb = h/p = 3.64 \u00d7 10\u207b\u00b9\u2070 m = 0.364 nm. Do not use E = pc for electron kinetic energy.</li></ol>__FIG_matter__</div>", "chapter": 2, "type": "worked"}, {"title": "Matter wave: accelerating potential", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> An electron starts from rest and accelerates through 100 V. Find K and \u03bb.</p><ol><li>K = eV = 1.60 \u00d7 10\u207b\u00b9\u2077 J = 100 eV, far below its 511 keV rest-energy scale.</li><li>p = \u221a(2mK) = \u221a(2 \u00d7 9.11 \u00d7 10\u207b\u00b3\u00b9 \u00d7 1.60 \u00d7 10\u207b\u00b9\u2077) = 5.40 \u00d7 10\u207b\u00b2\u2074 kg m/s.</li><li>\u03bb = h/p = 1.23 \u00d7 10\u207b\u00b9\u2070 m = 0.123 nm. The supplied non-relativistic model is appropriate.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Scaling: acceleration changes wavelength", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Compare non-relativistic electrons accelerated from rest through 25 V and 100 V.</p><ol><li>Because K = eV and p = \u221a(2meV), momentum scales as \u221aV.</li><li>Voltage rises by a factor 4, so momentum doubles and wavelength halves.</li><li>The 25 V wavelength is about 0.246 nm, twice the 100 V result. \u03bb is not inversely proportional to V itself.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Wavelength for a 2.00 eV emission, in nm", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Photon gap from \u22121.00 eV to \u22124.50 eV", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: levels", "html": "<div class=\"pp-page\">__FIG_levels__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: absorption", "html": "<div class=\"pp-page\">__FIG_absorption__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: matter", "html": "<div class=\"pp-page\">__FIG_matter__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Can a 3 eV photon excite any atom with a 3 eV gap somewhere in its diagram?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Can a 3 eV photon excite any atom with a 3 eV gap somewhere in its diagram?", "points": ["Only when the lower state of that matching transition is populated and the transition is allowed. Always identify the atom\u2019s initial state before testing absorption."], "claim": "Read discrete energy levels, distinguish emission from absorption, and calculate matter wavelengths without applying photon equations to electrons."}, "summary": "Read discrete energy levels, distinguish emission from absorption, and calculate matter wavelengths without applying photon equations to electrons."};const guides=[["Wavelength for a 2.00 eV emission, in nm", 621.5625, "nm", "\u03bb = hc/(2.00 \u00d7 1.60 \u00d7 10\u207b\u00b9\u2079) = 6.215625 \u00d7 10\u207b\u2077 m."], ["Photon gap from \u22121.00 eV to \u22124.50 eV", 3.5, "eV", "Emission energy is Ei \u2212 Ef = \u22121.00 \u2212 (\u22124.50) = 3.50 eV."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("Only when the lower state of that matching transition is populated and the transition is allowed. Always identify the atom\u2019s initial state before testing absorption.")));});C.register(s);}

{const s={"id": "young-double-slit", "parent": "quantum", "title": "Double slit: bright fringes, dark fringes and single particles", "shortTitle": "Double slit: bright fringes, dark fringes and single particles", "subtitle": "Build the two-path model, read interference evidence, and use explicitly supplied small-angle formulas for quantitative fringe scenarios.", "bank": [{"q": "For in-phase equal-amplitude slits, \u0394r = 2\u03bb is\u2026", "o": ["bright", "dark", "always central"], "a": 0, "explain": "Any whole-wavelength difference reinforces."}, {"q": "The first dark minimum has \u0394r\u2026", "o": ["0", "\u03bb/2", "\u03bb"], "a": 1, "explain": "The arrivals differ by half a cycle."}, {"q": "Path difference means\u2026", "o": ["r\u2081 + r\u2082", "|r\u2082 \u2212 r\u2081|", "L/d"], "a": 1, "explain": "Subtract the two routes."}, {"q": "With supplied \u0394y = \u03bbL/d, doubling d makes spacing\u2026", "o": ["twice", "half", "unchanged"], "a": 1, "explain": "Spacing is inversely proportional to separation."}, {"q": "One-at-a-time electron fringes show\u2026", "o": ["only electron\u2013electron collisions", "matter-wave interference with local detections", "no particle behaviour"], "a": 1, "explain": "No overlapping electrons are needed."}, {"q": "Reliable which-path information usually\u2026", "o": ["preserves ideal two-path coherence", "removes ideal two-path interference", "changes photon speed"], "a": 1, "explain": "The measurement changes the coherent alternatives."}], "practice": [{"q": "Two in-phase paths differ by 1.75 \u03bcm for 500 nm light. Classify the fringe and explain the role of equal amplitudes.", "points": ["\u0394r/\u03bb = 3.50, a half-integer.", "The arrivals are in opposite phase.", "Equal amplitudes give ideal cancellation; unequal amplitudes give a minimum that need not be completely dark."]}, {"q": "Use supplied \u0394y = \u03bbL/d for \u03bb = 650 nm, L = 1.50 m and d = 0.500 mm. Find spacing and second bright position.", "points": ["\u0394y = 1.95 \u00d7 10\u207b\u00b3 m = 1.95 mm.", "y\u2082 = 2\u0394y = 3.90 mm.", "The far-field small-angle approximation is assumed."]}], "pages": [{"title": "Two openings create two routes", "html": "<div class=\"pp-page\"><p>A wave arriving at two narrow slits spreads from both openings. At each screen location the two arriving contributions overlap; compare their path lengths to predict the resultant.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Coherence keeps the pattern stable", "html": "<div class=\"pp-page\"><p>Coherent sources have a stable phase relationship and the same frequency. A single source illuminating both slits supplies this relationship more reliably than two unrelated lamps.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Diffraction allows overlap", "html": "<div class=\"pp-page\"><p>Each slit diffracts the incident wave so it reaches a range of screen positions. Without overlapping contributions there would be no two-slit interference pattern in the overlap region.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Path difference is a subtraction", "html": "<div class=\"pp-page\"><p>At a point P, calculate \u0394r = |r\u2082 \u2212 r\u2081|. The interference condition depends on the difference, not the sum of both source-to-screen distances.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Equal paths give a central bright fringe", "html": "<div class=\"pp-page\"><p>For equal-phase illumination, the perpendicular bisector gives r\u2081 = r\u2082. \u0394r = 0 means the arrivals reinforce and the centre is a bright maximum.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Whole wavelengths give reinforcement", "html": "<div class=\"pp-page\"><p>With in-phase sources, \u0394r = m\u03bb gives constructive interference, where m = 0, 1, 2\u2026. The order number m counts maxima outward from the centre.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Half-integer differences give cancellation", "html": "<div class=\"pp-page\"><p>For equal-amplitude in-phase contributions, \u0394r = (m + \u00bd)\u03bb gives destructive interference. Real unequal amplitudes can leave nonzero intensity at minima.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Phase and path connect", "html": "<div class=\"pp-page\"><p>A path increase of one \u03bb corresponds to an extra phase cycle of 2\u03c0 radians. A \u03bb/2 difference gives opposite phase and cancellation for equal amplitudes.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Source phase matters too", "html": "<div class=\"pp-page\"><p>If the slits were driven out of phase, the equal-path centre would be dark for equal amplitudes. The familiar centre-bright rule assumes the source phase difference is zero.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A screen pattern is a spatial record", "html": "<div class=\"pp-page\"><p>Bright and dark bands mark different detector locations. They are not alternating times at which the entire screen turns bright or dark.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Supplied-formula extension: angular geometry", "html": "<div class=\"pp-page\"><p>For narrow slits separated by d, the far-field path difference is approximately d sin \u03b8. This quantitative geometry extends the syllabus\u2019s interference evidence and should be supplied when used.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Supplied-formula extension: small angles", "html": "<div class=\"pp-page\"><p>If screen distance L is much larger than slit separation and fringe displacement y is small compared with L, sin \u03b8 \u2248 tan \u03b8 \u2248 y/L. Then bright-fringe position is y\u2098 \u2248 m\u03bbL/d.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Supplied-formula extension: fringe spacing", "html": "<div class=\"pp-page\"><p>Adjacent bright maxima have spacing \u0394y \u2248 \u03bbL/d under the same far-field small-angle assumptions. A dark fringe lies halfway between ideal neighbouring bright fringes.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Read units before calculating fringes", "html": "<div class=\"pp-page\"><p>Slit separation often uses millimetres, screen displacement millimetres and wavelength nanometres. Convert all distances to metres before substituting; \u03bbL/d then has metre units.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Single photons arrive as local events", "html": "<div class=\"pp-page\"><p>At sufficiently low intensity a detector records separated photon arrivals. Each event is localised; many events build the same interference probability pattern.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Single electrons also show interference", "html": "<div class=\"pp-page\"><p>Electrons sent one at a time can accumulate an interference pattern. Use their de Broglie wavelength h/p in the wave model; a beam of classical tiny balls through two slits would not explain that pattern.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Which-path information changes the experiment", "html": "<div class=\"pp-page\"><p>A measurement that reliably identifies the slit taken destroys the two-path coherence needed for the ideal interference pattern. Avoid claiming the pattern vanishes merely because a person thinks about the path.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Double-slit fringes have an envelope", "html": "<div class=\"pp-page\"><p>Finite slit width produces a single-slit diffraction envelope that modulates fringe brightness. Equal fringe spacing in the small-angle region does not mean all maxima have identical intensity.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Direct path comparison: bright or dark", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> At P, two coherent in-phase paths are 2.0000000 m and 2.0000012 m. Light has \u03bb = 600 nm. Classify P.</p><ol><li>\u0394r = 1.2 \u00d7 10\u207b\u2076 m; \u03bb = 6.00 \u00d7 10\u207b\u2077 m.</li><li>\u0394r/\u03bb = 2.00, a whole number. The arrivals are in phase and form the m = 2 bright maximum.</li><li>Use the difference of routes, not their total distance.</li></ol>__FIG_slits__</div>", "chapter": 2, "type": "worked"}, {"title": "Dark scenario: count half wavelengths", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> At Q, the path difference is 900 nm for \u03bb = 600 nm.</p><ol><li>\u0394r/\u03bb = 900/600 = 1.50 = 1 + \u00bd.</li><li>For equal-amplitude in-phase slits the fields oppose, so Q is a dark minimum.</li><li>Changing both path lengths by the same amount leaves \u0394r and classification unchanged.</li></ol>__FIG_fringes__</div>", "chapter": 2, "type": "worked"}, {"title": "Supplied formula: calculate fringe spacing", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Use \u0394y = \u03bbL/d. Given \u03bb = 500 nm, L = 2.00 m, d = 0.250 mm, find adjacent bright spacing.</p><ol><li>Convert \u03bb = 5.00 \u00d7 10\u207b\u2077 m and d = 2.50 \u00d7 10\u207b\u2074 m. Assume far field and small angles.</li><li>\u0394y = (5.00 \u00d7 10\u207b\u2077 \u00d7 2.00)/(2.50 \u00d7 10\u207b\u2074) = 4.00 \u00d7 10\u207b\u00b3 m = 4.00 mm.</li><li>The third bright maximum is y\u2083 = 3\u0394y = 12.0 mm from the centre, not 3 mm.</li></ol>__FIG_fringegeometry__</div>", "chapter": 2, "type": "worked"}, {"title": "Reverse supplied-formula scenario: wavelength", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Bright spacing is 3.60 mm with d = 0.300 mm and L = 1.80 m. Infer \u03bb using \u03bb = \u0394y d/L.</p><ol><li>Convert \u0394y = 3.60 \u00d7 10\u207b\u00b3 m and d = 3.00 \u00d7 10\u207b\u2074 m.</li><li>\u03bb = (3.60 \u00d7 10\u207b\u00b3 \u00d7 3.00 \u00d7 10\u207b\u2074)/1.80 = 6.00 \u00d7 10\u207b\u2077 m = 600 nm.</li><li>The result is a visible wavelength. Leaving d in millimetres would make the result 1000 times too large.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Scaling scenario: change screen and slits", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Under \u0394y = \u03bbL/d, screen distance doubles and slit separation triples at fixed wavelength.</p><ol><li>Spacing is proportional to L and inversely proportional to d.</li><li>New spacing/old spacing = 2/3. An initial 6.00 mm spacing becomes 4.00 mm.</li><li>Increasing slit separation narrows the fringes; this differs from the diffraction envelope effect of changing slit width.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Evidence scenario: one electron at a time", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> One electron is in flight at a time. After many detections, a fringe pattern appears. Explain what this rules out.</p><ol><li>Individual detections are localised, showing particle-like detection events.</li><li>The accumulated distribution has interference maxima and minima, requiring a matter-wave description of the experiment.</li><li>The result rules out interference caused only by electrons colliding with one another. Reliable which-path detection would alter the coherent experiment.</li></ol>__FIG_singleparticle__</div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: For \u03bb = 400 nm, path difference 1.00 \u03bcm, enter \u0394r/\u03bb", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Supplied \u0394y = \u03bbL/d: \u03bb = 600 nm, L = 1 m, d = 0.2 mm; spacing in mm", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: slits", "html": "<div class=\"pp-page\">__FIG_slits__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: fringes", "html": "<div class=\"pp-page\">__FIG_fringes__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: singleparticle", "html": "<div class=\"pp-page\">__FIG_singleparticle__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Why does a central dark spot not automatically disprove wave interference?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Why does a central dark spot not automatically disprove wave interference?", "points": ["Source phase could be reversed, alignment could differ, or another optical element could add a phase shift. State the source phase and geometry before interpreting the centre."], "claim": "Build the two-path model, read interference evidence, and use explicitly supplied small-angle formulas for quantitative fringe scenarios."}, "summary": "Build the two-path model, read interference evidence, and use explicitly supplied small-angle formulas for quantitative fringe scenarios."};const guides=[["For \u03bb = 400 nm, path difference 1.00 \u03bcm, enter \u0394r/\u03bb", 2.5, "wavelengths", "1.00 \u00d7 10\u207b\u2076/(400 \u00d7 10\u207b\u2079) = 2.50: an ideal dark minimum."], ["Supplied \u0394y = \u03bbL/d: \u03bb = 600 nm, L = 1 m, d = 0.2 mm; spacing in mm", 3, "mm", "\u0394y = 600 \u00d7 10\u207b\u2079 \u00d7 1/(0.2 \u00d7 10\u207b\u00b3) = 0.003 m."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("Source phase could be reversed, alignment could differ, or another optical element could add a phase shift. State the source phase and geometry before interpreting the centre.")));});C.register(s);}

{const s={"id": "light-polarisation", "parent": "quantum", "title": "Polarisation: transverse fields and filter angles", "shortTitle": "Polarisation: transverse fields and filter angles", "subtitle": "Understand what a polariser selects, distinguish one filter from crossed filters, and use a supplied Malus-law extension for angle calculations.", "bank": [{"q": "Polarisation is evidence that light is\u2026", "o": ["transverse", "longitudinal", "slower than sound"], "a": 0, "explain": "The electric-field orientation is perpendicular to propagation."}, {"q": "One ideal filter with unpolarised input gives\u2026", "o": ["I\u2080", "I\u2080/2", "zero"], "a": 1, "explain": "Average over input orientations."}, {"q": "Supplied Malus law uses\u2026", "o": ["cos \u03b8", "cos\u00b2\u03b8", "sin \u03b8 always"], "a": 1, "explain": "Intensity is proportional to squared field amplitude."}, {"q": "Crossed ideal filters have relative angle\u2026", "o": ["0\u00b0", "45\u00b0", "90\u00b0"], "a": 2, "explain": "No field component lies along the crossed analyser axis."}, {"q": "With three filters, next \u03b8 is measured between\u2026", "o": ["neighbouring axes", "first axis and every later filter", "axis and beam direction"], "a": 0, "explain": "Each output is polarised along the preceding filter."}, {"q": "An ideal polariser changes a fixed-colour beam primarily by\u2026", "o": ["changing hf", "reducing transmitted photon flux", "changing c"], "a": 1, "explain": "It selects orientation while frequency remains fixed."}], "practice": [{"q": "Unpolarised 120 W/m\u00b2 passes two ideal filters at relative angle 30\u00b0. Use supplied Iout = Iin cos\u00b2\u03b8. Find each output.", "points": ["First output = 120/2 = 60 W/m\u00b2.", "Second = 60 \u00d7 0.75 = 45 W/m\u00b2.", "The second output is polarised along the analyser axis."]}, {"q": "Polarised intensity is reduced from 32 to 8 W/m\u00b2 by an ideal analyser. Use supplied Malus law to find \u03b8 in 0\u00b0\u201390\u00b0.", "points": ["Iout/Iin = 0.25 = cos\u00b2\u03b8.", "cos \u03b8 = 0.50; \u03b8 = 60\u00b0.", "Do not introduce a first-filter half factor for already polarised input."]}], "pages": [{"title": "Polarisation concerns field orientation", "html": "<div class=\"pp-page\"><p>For light travelling in a fixed direction, polarisation describes the direction of its electric-field oscillation. It is not the direction in which the beam travels.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A transverse wave has available orientations", "html": "<div class=\"pp-page\"><p>The electric field can oscillate in different directions perpendicular to propagation. This sideways freedom allows a polariser to select one orientation.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Longitudinal waves do not polarise this way", "html": "<div class=\"pp-page\"><p>A longitudinal oscillation is parallel to travel, so there is not an equivalent range of transverse orientations for a filter to select. Polarisation therefore supports a transverse model of light.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Unpolarised light has many orientations", "html": "<div class=\"pp-page\"><p>Over time, unpolarised light has no single fixed electric-field orientation. Do not draw it as two permanently perpendicular beams with separate colours.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A transmission axis selects a component", "html": "<div class=\"pp-page\"><p>An ideal linear polariser transmits the electric-field component along its transmission axis. The perpendicular component is not transmitted; absorption or reflection depends on the real device.</p></div>", "chapter": 0, "type": "learn"}, {"title": "One polariser gives linearly polarised light", "html": "<div class=\"pp-page\"><p>After one ideal filter, the emerging electric field oscillates along its transmission axis. The output is polarised even though the input was unpolarised.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Ideal unpolarised intensity halves", "html": "<div class=\"pp-page\"><p>Averaging all transverse orientations gives transmitted intensity I = I\u2080/2 for an ideal filter illuminated by unpolarised light. Real absorption can reduce transmission further.</p></div>", "chapter": 0, "type": "learn"}, {"title": "An analyser tests the first filter", "html": "<div class=\"pp-page\"><p>A second polariser is often called an analyser. Its angle is measured relative to the already polarised electric field from the first filter, not relative to the page or beam direction.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Parallel axes transmit most strongly", "html": "<div class=\"pp-page\"><p>If the ideal analyser axis matches the incident linear polarisation, it transmits the full ideal input intensity to that analyser. Any real losses are additional.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Crossed axes block the component", "html": "<div class=\"pp-page\"><p>At a relative angle of 90\u00b0, the incident field has zero component along the analyser axis. Ideal crossed polarisers therefore give zero transmitted intensity.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Supplied-formula extension: field projection", "html": "<div class=\"pp-page\"><p>For incident field amplitude E\u2080 and relative angle \u03b8, the transmitted amplitude is E\u2080 cos \u03b8. This geometric projection is the starting point for quantitative angle calculations.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Supplied-formula extension: Malus law", "html": "<div class=\"pp-page\"><p>Intensity is proportional to the square of field amplitude, so I = Iin cos\u00b2\u03b8 for linearly polarised input and an ideal analyser. This quantitative law is used here as an explicitly supplied extension.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A 45-degree analyser halves intensity", "html": "<div class=\"pp-page\"><p>cos\u00b245\u00b0 = \u00bd. This applies to polarised intensity entering the analyser; unpolarised light passing through two filters at 45\u00b0 gives I\u2080/4 overall.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Choose the correct input for each filter", "html": "<div class=\"pp-page\"><p>For multiple filters, calculate stage by stage. The polarisation after each filter follows its own axis, so the next angle is the difference between neighbouring axes.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A middle filter can restore transmission", "html": "<div class=\"pp-page\"><p>Between crossed filters, adding a 45\u00b0 filter changes the polarisation in two steps. Some light then passes the final filter even though the original two-filter crossed arrangement transmitted none.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Solve inverse angle with a square root", "html": "<div class=\"pp-page\"><p>If I/Iin is known, first take \u221a(I/Iin) = |cos \u03b8|, then find a suitable angle. For the common 0\u00b0\u201390\u00b0 range, \u03b8 = cos\u207b\u00b9\u221a(I/Iin).</p></div>", "chapter": 1, "type": "learn"}, {"title": "Glare reduction has a physical context", "html": "<div class=\"pp-page\"><p>Reflection from a non-metallic surface can preferentially polarise light. A correctly oriented filter reduces that component, explaining many sunglasses applications without claiming all reflected light is perfectly polarised.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Separate intensity loss from colour", "html": "<div class=\"pp-page\"><p>An ideal polariser selects orientation, not photon frequency. Reducing intensity reduces transmitted photon rate at fixed colour; it does not automatically reduce photon energy.</p></div>", "chapter": 1, "type": "learn"}, {"title": "One ideal filter: unpolarised input", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Unpolarised light has intensity 80.0 W/m\u00b2. Find output after one ideal polariser.</p><ol><li>The input is unpolarised, so use the orientation average I = I\u2080/2.</li><li>I = 40.0 W/m\u00b2; the output is linearly polarised along the filter axis.</li><li>Do not apply cos\u00b2\u03b8 to a single fixed input angle because none is specified for unpolarised light.</li></ol>__FIG_polarone__</div>", "chapter": 2, "type": "worked"}, {"title": "Supplied Malus law: two filters at 60\u00b0", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> The first filter receives unpolarised 80.0 W/m\u00b2; the second is 60\u00b0 from the first. Use Iout = Iin cos\u00b2\u03b8.</p><ol><li>After the first filter: 40.0 W/m\u00b2. This is the input to the analyser.</li><li>cos\u00b260\u00b0 = 0.25, so Iout = 40.0 \u00d7 0.25 = 10.0 W/m\u00b2.</li><li>Overall transmission is 12.5% of the original beam, not 25%.</li></ol>__FIG_polartwo__</div>", "chapter": 2, "type": "worked"}, {"title": "Already polarised input: avoid halving twice", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Linearly polarised light at 50.0 W/m\u00b2 enters an analyser at 30\u00b0. Find output using supplied Malus law.</p><ol><li>There is no unpolarised first-filter averaging step in this question.</li><li>Iout = 50.0 cos\u00b230\u00b0 = 50.0 \u00d7 0.75 = 37.5 W/m\u00b2.</li><li>The emerging field follows the analyser axis; photon frequency is unchanged.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Reverse supplied-formula scenario: angle", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> An analyser reduces linearly polarised light to one quarter of its input intensity. Find \u03b8 between 0\u00b0 and 90\u00b0.</p><ol><li>Iout/Iin = cos\u00b2\u03b8 = 0.25.</li><li>cos \u03b8 = \u221a0.25 = 0.50, giving \u03b8 = 60\u00b0.</li><li>Using cos\u207b\u00b9(0.25) would be wrong because intensity uses a squared projection.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Three filters: a middle orientation matters", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Unpolarised 100 W/m\u00b2 passes ideal axes at 0\u00b0, 45\u00b0 and 90\u00b0. Find output with supplied Malus law.</p><ol><li>First filter gives 50 W/m\u00b2 and 0\u00b0 polarisation.</li><li>Second differs by 45\u00b0: 50 \u00d7 \u00bd = 25 W/m\u00b2; its output is polarised at 45\u00b0.</li><li>Third differs from the second by 45\u00b0: 25 \u00d7 \u00bd = 12.5 W/m\u00b2. Without the middle filter, 0\u00b0 and 90\u00b0 would transmit zero ideally.</li></ol>__FIG_polarthree__</div>", "chapter": 2, "type": "worked"}, {"title": "Evidence scenario: light versus sound", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Rotating an analyser gives alternating maximum and near-zero transmitted light. Why is this evidence for a transverse wave?</p><ol><li>The rotation changes the analyser\u2019s transverse transmission direction.</li><li>A changing transmitted component means the wave has an oscillation orientation perpendicular to travel.</li><li>Ordinary longitudinal sound in air lacks this transverse orientation choice, so this polarisation mechanism does not apply to it.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Supplied Malus law: polarised input 24 W/m\u00b2, relative angle 45\u00b0", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Unpolarised 60 W/m\u00b2 through one ideal filter", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: polarone", "html": "<div class=\"pp-page\">__FIG_polarone__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: polartwo", "html": "<div class=\"pp-page\">__FIG_polartwo__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: polarthree", "html": "<div class=\"pp-page\">__FIG_polarthree__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Why can inserting a middle polariser increase transmission between crossed filters?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Why can inserting a middle polariser increase transmission between crossed filters?", "points": ["It changes the transmitted polarisation orientation in stages. Each neighbour pair then has a nonzero projected component; the new arrangement is a different experiment, not a violation of energy conservation."], "claim": "Understand what a polariser selects, distinguish one filter from crossed filters, and use a supplied Malus-law extension for angle calculations."}, "summary": "Understand what a polariser selects, distinguish one filter from crossed filters, and use a supplied Malus-law extension for angle calculations."};const guides=[["Supplied Malus law: polarised input 24 W/m\u00b2, relative angle 45\u00b0", 12, "W/m\u00b2", "I = 24 cos\u00b245\u00b0 = 12 W/m\u00b2."], ["Unpolarised 60 W/m\u00b2 through one ideal filter", 30, "W/m\u00b2", "Average ideal transmission is I\u2080/2."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("It changes the transmitted polarisation orientation in stages. Each neighbour pair then has a nonzero projected component; the new arrangement is a different experiment, not a violation of energy conservation.")));});C.register(s);}

{const s={"id": "black-body-radiation", "parent": "quantum", "title": "Black-body radiation: temperature, spectra and quantum limits", "shortTitle": "Black-body radiation: temperature, spectra and quantum limits", "subtitle": "Read thermal spectra correctly, explain the failure of classical predictions, and apply clearly supplied temperature and power extensions.", "bank": [{"q": "A thermal wavelength-spectrum peak moves shorter when T\u2026", "o": ["rises", "falls", "stays fixed"], "a": 0, "explain": "Hotter black bodies peak at shorter wavelength."}, {"q": "Total spectral area represents\u2026", "o": ["only peak wavelength", "total power over the plotted range", "one photon energy"], "a": 1, "explain": "It sums contributions across wavelength intervals."}, {"q": "A black body at room temperature\u2026", "o": ["does not radiate", "radiates mainly in infrared", "emits only visible light"], "a": 1, "explain": "All objects above absolute zero emit thermal radiation."}, {"q": "Supplied thermal laws use\u2026", "o": ["Celsius ratios", "kelvin", "electronvolts as temperature"], "a": 1, "explain": "Absolute temperature is required."}, {"q": "Classical ultraviolet catastrophe predicts\u2026", "o": ["too much short-wavelength radiation", "no light at all", "only one line"], "a": 0, "explain": "The measured finite short-wavelength decline contradicts the classical result."}, {"q": "Supplied P \u221d T\u2074: double T at fixed area gives\u2026", "o": ["2P", "4P", "16P"], "a": 2, "explain": "2\u2074 = 16."}], "practice": [{"q": "Use supplied \u03bbmaxT = 2.90 \u00d7 10\u207b\u00b3 m K for peaks at 0.800 \u03bcm and 1.60 \u03bcm. Find temperatures and equal-area emitted-power ratio using supplied P \u221d T\u2074.", "points": ["Temperatures are 3625 K and 1812.5 K.", "The first is twice as hot in kelvin.", "Its power per equal area is 2\u2074 = 16 times larger."]}, {"q": "Explain why the classical ultraviolet prediction disagrees with an observed thermal spectrum and how quantised exchange helps.", "points": ["Classical equipartition predicts excessive unbounded high-frequency radiation.", "Measured spectra have a finite maximum and decline at short wavelengths.", "Energy quanta hf make high-frequency excitations require larger energy, matching the observed suppression."]}], "pages": [{"title": "Thermal radiation is emitted by warm matter", "html": "<div class=\"pp-page\"><p>Objects emit electromagnetic radiation because of their thermal energy. This emission does not require visible glowing: room-temperature objects radiate mainly in the infrared.</p></div>", "chapter": 0, "type": "learn"}, {"title": "An ideal black body absorbs all incident radiation", "html": "<div class=\"pp-page\"><p>A black body is an ideal absorber at every wavelength and direction. At a given temperature it is also the ideal thermal emitter; being called black does not mean it cannot glow.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A cavity approximates the ideal model", "html": "<div class=\"pp-page\"><p>A small hole into a heated cavity traps most incoming radiation through repeated absorption. Radiation emerging from the hole approximates a black-body spectrum set by the cavity temperature.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A spectrum distributes power across wavelengths", "html": "<div class=\"pp-page\"><p>A wavelength spectrum plots emitted power per wavelength interval against wavelength. The height at one wavelength is not the total emitted power; the area across the spectrum represents that total.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Black-body spectra are continuous", "html": "<div class=\"pp-page\"><p>The spectrum spans many wavelengths rather than a few atomic lines. A thermal continuum can coexist with emission or absorption lines from particular materials or surrounding gases.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The peak is a distribution maximum", "html": "<div class=\"pp-page\"><p>Peak wavelength is where the wavelength-based spectral curve is highest. It does not mean the object emits only that wavelength; substantial radiation occurs on both sides.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Hotter objects peak at shorter wavelengths", "html": "<div class=\"pp-page\"><p>As temperature rises, the wavelength-spectrum maximum moves toward shorter \u03bb. This qualitative temperature dependence is core; the numerical Wien relationship below is a supplied extension.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Hotter objects emit more overall energy", "html": "<div class=\"pp-page\"><p>At a higher temperature the spectrum rises and its total area increases. Compare total area for power, and peak location for characteristic wavelength; they describe different aspects.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Use absolute temperature", "html": "<div class=\"pp-page\"><p>Thermal spectral laws use kelvin. Convert Celsius using T(K) = t(\u00b0C) + 273.15; a percentage temperature change must use kelvin rather than Celsius values.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The classical short-wavelength prediction fails", "html": "<div class=\"pp-page\"><p>Classical equipartition applied to radiation modes predicts unbounded radiation toward high frequency, unlike the measured finite spectrum. This failure is called the ultraviolet catastrophe.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Planck introduces discrete exchange", "html": "<div class=\"pp-page\"><p>Planck\u2019s successful model quantises energy exchange in multiples of hf. At high frequency a quantum needs more energy, suppressing the population of high-energy excitations and correcting the classical prediction.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Quantum success does not delete waves", "html": "<div class=\"pp-page\"><p>The radiation still propagates with electromagnetic-wave properties. Quantised emission and absorption explain its thermal energy distribution; wave behaviour remains necessary for diffraction and interference.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Supplied extension: Wien\u2019s displacement law", "html": "<div class=\"pp-page\"><p>Use \u03bbmax T = b, where b = 2.90 \u00d7 10\u207b\u00b3 m K is supplied here. This quantitative law is not explicitly named in the 2026 syllabus core statements; qualitative spectral shifts remain the core goal.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Supplied extension: Stefan\u2013Boltzmann emission", "html": "<div class=\"pp-page\"><p>For an ideal black-body surface, emitted power P = \u03c3AT\u2074 with supplied \u03c3 = 5.67 \u00d7 10\u207b\u2078 W m\u207b\u00b2 K\u207b\u2074. It uses emitting area A and absolute temperature T.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Real surfaces have emissivity", "html": "<div class=\"pp-page\"><p>A grey-body extension uses P = \u03b5\u03c3AT\u2074, with 0 \u2264 \u03b5 \u2264 1. The simplified constant \u03b5 model can approximate some materials; real emissivity may depend on wavelength and direction.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Net radiative transfer includes surroundings", "html": "<div class=\"pp-page\"><p>In a supplied grey-body model, Pnet = \u03b5\u03c3A(T\u2074 \u2212 Ts\u2074). Emission continues even when surroundings radiate back; zero net transfer at equal temperature does not mean zero emitted radiation.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Compare ratios before long arithmetic", "html": "<div class=\"pp-page\"><p>With area and emissivity fixed, P\u2082/P\u2081 = (T\u2082/T\u2081)\u2074. Doubling kelvin temperature gives 16 times emitted power, while \u03bbmax halves under the supplied Wien law.</p></div>", "chapter": 1, "type": "learn"}, {"title": "State what the plotted spectrum represents", "html": "<div class=\"pp-page\"><p>A spectrum plotted against frequency has a different peak location from one plotted against wavelength because the interval measure changes. Use the wavelength-specific Wien constant only for a wavelength spectrum.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Qualitative graph scenario: which is hotter?", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Two wavelength spectra have peaks at 1.00 \u03bcm and 2.00 \u03bcm. Identify the hotter black body.</p><ol><li>The shorter-wavelength peak belongs to the hotter body. This conclusion does not require a numerical constant.</li><li>Its total emitted power per equal area is also greater; the diagram\u2019s curve area, not just peak position, represents power.</li><li>Under supplied Wien law, the temperatures differ by a factor two.</li></ol>__FIG_thermalcurves__</div>", "chapter": 2, "type": "worked"}, {"title": "Supplied Wien law: a stellar surface", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A black body peaks at 500 nm. Use \u03bbmax T = 2.90 \u00d7 10\u207b\u00b3 m K to estimate T.</p><ol><li>Convert 500 nm to 5.00 \u00d7 10\u207b\u2077 m.</li><li>T = b/\u03bbmax = 2.90 \u00d7 10\u207b\u00b3/(5.00 \u00d7 10\u207b\u2077) = 5800 K.</li><li>This assumes the observed peak is the wavelength-spectrum thermal maximum, not an isolated atomic spectral line.</li></ol>__FIG_thermalpeak__</div>", "chapter": 2, "type": "worked"}, {"title": "Supplied Wien law: room-temperature radiation", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> At 300 K, find peak wavelength with b = 2.90 \u00d7 10\u207b\u00b3 m K.</p><ol><li>\u03bbmax = b/T = 2.90 \u00d7 10\u207b\u00b3/300 = 9.67 \u00d7 10\u207b\u2076 m = 9.67 \u03bcm.</li><li>The peak is infrared, explaining why the object does not visibly glow even though it radiates.</li><li>Do not substitute 27\u00b0C directly: the law requires kelvin.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Supplied Stefan\u2013Boltzmann law: emitted power", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> An ideal black body has emitting area 0.0100 m\u00b2 and T = 1000 K. Use P = \u03c3AT\u2074.</p><ol><li>T\u2074 = (1000)\u2074 = 1.00 \u00d7 10\u00b9\u00b2 K\u2074.</li><li>P = (5.67 \u00d7 10\u207b\u2078)(0.0100)(1.00 \u00d7 10\u00b9\u00b2) = 567 W.</li><li>This is emitted power, before subtracting radiation received from surroundings.</li></ol>__FIG_thermalpower__</div>", "chapter": 2, "type": "worked"}, {"title": "Supplied net-transfer model: a warm surface", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Use \u03b5 = 1, A = 0.0200 m\u00b2, T = 400 K and Ts = 300 K in Pnet = \u03b5\u03c3A(T\u2074 \u2212 Ts\u2074).</p><ol><li>T\u2074 = 2.56 \u00d7 10\u00b9\u2070; Ts\u2074 = 8.10 \u00d7 10\u2079; difference = 1.75 \u00d7 10\u00b9\u2070 K\u2074.</li><li>Pnet = (5.67 \u00d7 10\u207b\u2078)(0.0200)(1.75 \u00d7 10\u00b9\u2070) = 19.8 W outward.</li><li>The surface emits about 29.0 W but also receives about 9.19 W in this idealised exchange model.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Supplied ratio scenario: area and temperature", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A black body\u2019s emitting area halves while kelvin temperature doubles. Find emitted-power ratio.</p><ol><li>P \u221d AT\u2074, so Pnew/Pold = (\u00bd)(2\u2074) = 8.</li><li>The new total emitted power is eight times larger despite the smaller area.</li><li>The peak wavelength halves by Wien law. Emitting area affects power but not ideal thermal peak position.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Supplied Wien law: peak wavelength 1.00 \u03bcm; find T", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: At fixed area and \u03b5, T rises from 300 K to 600 K; supplied power ratio", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: thermalcurves", "html": "<div class=\"pp-page\">__FIG_thermalcurves__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: thermalpeak", "html": "<div class=\"pp-page\">__FIG_thermalpeak__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: thermalpower", "html": "<div class=\"pp-page\">__FIG_thermalpower__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Can a black body be red-hot while still being an ideal absorber?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Can a black body be red-hot while still being an ideal absorber?", "points": ["Yes. Black-body describes perfect absorption of incident radiation. Its own thermal emission becomes visible at sufficiently high temperature, so the name does not prohibit visible glowing."], "claim": "Read thermal spectra correctly, explain the failure of classical predictions, and apply clearly supplied temperature and power extensions."}, "summary": "Read thermal spectra correctly, explain the failure of classical predictions, and apply clearly supplied temperature and power extensions."};const guides=[["Supplied Wien law: peak wavelength 1.00 \u03bcm; find T", 2900, "K", "T = 2.90 \u00d7 10\u207b\u00b3/(1.00 \u00d7 10\u207b\u2076) = 2900 K."], ["At fixed area and \u03b5, T rises from 300 K to 600 K; supplied power ratio", 16, "ratio", "(600/300)\u2074 = 16; use kelvin."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("Yes. Black-body describes perfect absorption of incident radiation. Its own thermal emission becomes visible at sufficiently high temperature, so the name does not prohibit visible glowing.")));});C.register(s);}

{const s={"id": "photoelectric-planck-investigation", "parent": "quantum", "title": "Measure Planck\u2019s constant: stopping-potential graphs and uncertainty", "shortTitle": "Measure Planck\u2019s constant: stopping-potential graphs and uncertainty", "subtitle": "Design a controlled photoelectric investigation, transform data with correct axis units, and infer h, work function and threshold with honest uncertainty.", "bank": [{"q": "On Vs versus f, gradient equals\u2026", "o": ["h", "h/e", "e/h"], "a": 1, "explain": "Vs = (h/e)f \u2212 \u03c6/e."}, {"q": "On K in joules versus f, gradient equals\u2026", "o": ["h", "h/e", "\u03c6"], "a": 0, "explain": "K = hf \u2212 \u03c6."}, {"q": "A horizontal axis f/(10\u00b9\u2074 Hz) requires gradient conversion by\u2026", "o": ["multiplying by 10\u00b9\u2074", "dividing by 10\u00b9\u2074", "no factor"], "a": 1, "explain": "A plotted frequency unit corresponds to 10\u00b9\u2074 Hz."}, {"q": "A \u22122 V intercept implies \u03c6\u2026", "o": ["\u22122 eV", "2 eV", "2 J"], "a": 1, "explain": "\u03c6 is the positive energy needed to escape."}, {"q": "A constant voltage offset primarily changes\u2026", "o": ["the intercept", "Planck\u2019s true constant", "light speed"], "a": 0, "explain": "A uniform y shift leaves the ideal gradient unchanged."}, {"q": "Repeats alone remove\u2026", "o": ["all systematic error", "some random uncertainty in the mean", "unknown calibration offsets"], "a": 1, "explain": "Systematic effects require calibration or modelling."}], "practice": [{"q": "On a Vs plot against f/(10\u00b9\u2074 Hz), a fitted line has slope 0.420 V per unit and intercept \u22122.10 V. Find h and f\u2080.", "points": ["h = (1.60 \u00d7 10\u207b\u00b9\u2079)(0.420/10\u00b9\u2074) = 6.72 \u00d7 10\u207b\u00b3\u2074 J s.", "Threshold x\u2080 = 2.10/0.420 = 5.00.", "f\u2080 = 5.00 \u00d7 10\u00b9\u2074 Hz; \u03c6 = 2.10 eV."]}, {"q": "Describe two controls and one source of systematic uncertainty in a photoelectric measurement of h.", "points": ["Keep the same surface and stable collection geometry.", "Use calibrated narrow-band frequencies and background-current correction.", "A calibration or contact-potential voltage offset can bias the intercept; repeats alone do not remove it."]}], "pages": [{"title": "Ask a measurable question", "html": "<div class=\"pp-page\"><p>The investigation tests how maximum photoelectron kinetic energy changes with incident frequency for one surface. Frequency is the independent variable and stopping-potential magnitude is the measured response.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Predict a straight-line relationship", "html": "<div class=\"pp-page\"><p>Kmax = hf \u2212 \u03c6 predicts a line above threshold. Measuring Vs gives Kmax = eVs, so Vs = (h/e)f \u2212 \u03c6/e.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Choose one surface throughout", "html": "<div class=\"pp-page\"><p>Changing the metal changes \u03c6 and therefore the intercept. Use the same clean photoemissive surface, stable temperature and unchanged collection geometry to isolate frequency effects.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Use narrow frequency bands", "html": "<div class=\"pp-page\"><p>A broad source contains photons at many frequencies, and the highest-energy photons can dominate the stopping point. Use known narrow-band light and include its bandwidth in the uncertainty discussion.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Measure frequency from wavelength", "html": "<div class=\"pp-page\"><p>If filters or lamps are specified by wavelength, convert to metres and use f = c/\u03bb. Frequency uncertainty arises from wavelength calibration and bandwidth.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Find a stopping point rather than saturation current", "html": "<div class=\"pp-page\"><p>Increase the retarding voltage until the collected photoelectric current reaches the background level. Saturation current measures emission rate and is not the direct response needed for maximum energy.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Account for background current", "html": "<div class=\"pp-page\"><p>Record a dark or blocked-light baseline. A nonzero leakage current means a stopping criterion must compare with the baseline, rather than forcing the measured current to absolute zero.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Repeat readings to assess scatter", "html": "<div class=\"pp-page\"><p>Take repeat stopping-potential measurements for each frequency. Means reduce random scatter; repeated measurements do not automatically remove a systematic offset or incorrect calibration.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Use several frequencies above threshold", "html": "<div class=\"pp-page\"><p>Spread the frequencies across an adequate range while remaining above threshold. A narrow cluster makes a gradient more uncertain because \u0394f is small relative to measurement errors.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Plot the independent variable horizontally", "html": "<div class=\"pp-page\"><p>Plot f in Hz on the horizontal axis and Vs in V vertically, with units and uncertainty bars. Fit a line to the trend rather than connecting successive points as a zigzag.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Gradient on a Vs\u2013f graph is h/e", "html": "<div class=\"pp-page\"><p>From Vs = (h/e)f \u2212 \u03c6/e, slope has units V s. Multiply the fitted slope by e to obtain h in J s.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Gradient on a K\u2013f graph is h", "html": "<div class=\"pp-page\"><p>If you first convert Vs to K in joules, the gradient directly gives h. Do not multiply by e a second time after converting the vertical axis to joules.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Scaled horizontal axes need a factor", "html": "<div class=\"pp-page\"><p>If the horizontal label is f/(10\u00b9\u2074 Hz), one plotted unit represents 10\u00b9\u2074 Hz. Divide a gradient in volts per plotted unit by 10\u00b9\u2074 before treating it as h/e.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Electronvolt vertical axes need care", "html": "<div class=\"pp-page\"><p>For a K axis in eV, slope in eV/Hz must be multiplied by 1.60 \u00d7 10\u207b\u00b9\u2079 J/eV to obtain h in J s. Numerically, K in eV equals Vs in volts for an electron, but the units are different.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Vertical intercept gives work function", "html": "<div class=\"pp-page\"><p>For a Vs graph, extrapolated intercept B = \u2212\u03c6/e. Thus \u03c6 = \u2212eB in joules, or \u03c6 in eV equals the positive magnitude of B in volts under the electronvolt conversion.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Horizontal intercept gives threshold", "html": "<div class=\"pp-page\"><p>At Vs = 0, f\u2080 = \u2212B/M for Vs = Mf + B. This is an extrapolated threshold; points far from the crossing can make its uncertainty substantial.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Estimate a justified gradient range", "html": "<div class=\"pp-page\"><p>Draw or calculate steepest and shallowest plausible lines consistent with uncertainties. Their slopes estimate the range of h; do not assume error bars vanish because the best-fit line looks straight.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Distinguish random and systematic effects", "html": "<div class=\"pp-page\"><p>Scatter among repeats suggests random variation; a contact-potential offset can shift the intercept systematically. A constant voltage offset may leave slope similar while biasing work function and threshold.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Ideal data: build the scaled-axis gradient", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A fitted line on Vs versus x = f/(10\u00b9\u2074 Hz) passes (6.00, 0.486 V) and (10.00, 2.1435 V). Infer h.</p><ol><li>Plotted gradient = (2.1435 \u2212 0.486)/(10.00 \u2212 6.00) = 0.414375 V per plotted unit.</li><li>Actual M = 0.414375/10\u00b9\u2074 = 4.14375 \u00d7 10\u207b\u00b9\u2075 V s.</li><li>h = eM = (1.60 \u00d7 10\u207b\u00b9\u2079)(4.14375 \u00d7 10\u207b\u00b9\u2075) = 6.63 \u00d7 10\u207b\u00b3\u2074 J s. Use well-separated points on the fitted line.</li></ol>__FIG_plankgraph__</div>", "chapter": 2, "type": "worked"}, {"title": "Intercept scenario: work function and threshold", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> The fitted line is Vs = 0.414375x \u2212 2.00 with x = f/(10\u00b9\u2074 Hz). Find \u03c6 and f\u2080.</p><ol><li>Vertical intercept is \u22122.00 V, so \u03c6 = 2.00 eV = 3.20 \u00d7 10\u207b\u00b9\u2079 J.</li><li>Set Vs = 0: x\u2080 = 2.00/0.414375 = 4.82655.</li><li>f\u2080 = 4.83 \u00d7 10\u00b9\u2074 Hz. The extrapolated negative-voltage part is not a physical negative kinetic energy.</li></ol>__FIG_threshold__</div>", "chapter": 2, "type": "worked"}, {"title": "Joule-axis scenario: no extra e factor", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A Kmax-versus-f graph has slope 6.70 \u00d7 10\u207b\u00b3\u2074 J s and intercept \u22123.50 \u00d7 10\u207b\u00b9\u2079 J.</p><ol><li>Because the vertical quantity is already K in joules, h is directly the slope: 6.70 \u00d7 10\u207b\u00b3\u2074 J s.</li><li>Work function is minus the intercept: \u03c6 = 3.50 \u00d7 10\u207b\u00b9\u2079 J = 2.19 eV.</li><li>Multiplying the gradient by e again would give incorrect units and a value much too small.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Uncertainty scenario: slope limits", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> On the scaled Vs\u2013x plot, plausible slopes range from 0.390 to 0.430 V per unit. Estimate h and its half-range uncertainty.</p><ol><li>Central slope = (0.390 + 0.430)/2 = 0.410; half range = 0.020 V per unit.</li><li>h = e(0.410/10\u00b9\u2074) = 6.56 \u00d7 10\u207b\u00b3\u2074 J s.</li><li>Absolute half-range = e(0.020/10\u00b9\u2074) = 0.32 \u00d7 10\u207b\u00b3\u2074 J s; percentage \u2248 4.88%. Report (6.56 \u00b1 0.32) \u00d7 10\u207b\u00b3\u2074 J s.</li></ol>__FIG_uncertainty__</div>", "chapter": 2, "type": "worked"}, {"title": "Wavelength calibration: frequency uncertainty", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A source is specified as (500 \u00b1 5) nm. Estimate frequency and percentage uncertainty for small errors.</p><ol><li>f = c/\u03bb = 6.00 \u00d7 10\u00b9\u2074 Hz.</li><li>For the inverse relation, approximate fractional uncertainty magnitude \u03b4f/f \u2248 \u03b4\u03bb/\u03bb = 5/500 = 1%.</li><li>\u03b4f \u2248 0.06 \u00d7 10\u00b9\u2074 Hz. Frequency moves in the opposite direction to wavelength, but uncertainty magnitude is positive.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Systematic offset: intercept versus slope", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Every stopping-potential reading contains a constant +0.200 V offset. Explain fitted parameters.</p><ol><li>Adding the same amount to every y value shifts the intercept upward by 0.200 V while leaving \u0394Vs and gradient unchanged.</li><li>The inferred h from slope is unchanged in this ideal constant-offset case.</li><li>If \u03c6 is inferred as the negative intercept magnitude, it is underestimated by 0.200 eV; the threshold intercept is also biased. Calibration and contact-potential checks matter.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: A scaled Vs\u2013x gradient is 0.400 V per unit, x = f/(10\u00b9\u2074 Hz). Enter inferred h in units 10\u207b\u00b3\u2074 J s", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Intercept \u22121.80 V on Vs\u2013f graph: work function in eV", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: plankgraph", "html": "<div class=\"pp-page\">__FIG_plankgraph__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: peapparatus", "html": "<div class=\"pp-page\">__FIG_peapparatus__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: uncertainty", "html": "<div class=\"pp-page\">__FIG_uncertainty__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Why is choosing two neighbouring raw data points usually weaker than using a fitted line over a wide frequency range?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Why is choosing two neighbouring raw data points usually weaker than using a fitted line over a wide frequency range?", "points": ["Small \u0394f makes the gradient sensitive to random voltage errors. A justified fit uses all data; well-separated points on that fit give a more stable gradient, with uncertainty still reported."], "claim": "Design a controlled photoelectric investigation, transform data with correct axis units, and infer h, work function and threshold with honest uncertainty."}, "summary": "Design a controlled photoelectric investigation, transform data with correct axis units, and infer h, work function and threshold with honest uncertainty."};const guides=[["A scaled Vs\u2013x gradient is 0.400 V per unit, x = f/(10\u00b9\u2074 Hz). Enter inferred h in units 10\u207b\u00b3\u2074 J s", 6.4, "\u00d7 10\u207b\u00b3\u2074 J s", "h = e \u00d7 0.400/10\u00b9\u2074 = 6.40 \u00d7 10\u207b\u00b3\u2074 J s."], ["Intercept \u22121.80 V on Vs\u2013f graph: work function in eV", 1.8, "eV", "B = \u2212\u03c6/e; \u03c6 is positive 1.80 eV."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("Small \u0394f makes the gradient sensitive to random voltage errors. A justified fit uses all data; well-separated points on that fit give a more stable gradient, with uncertainty still reported.")));});C.register(s);}

{const s={"id": "fluorescence-phosphorescence", "parent": "quantum", "title": "Fluorescence and phosphorescence: prompt and delayed light", "shortTitle": "Fluorescence and phosphorescence: prompt and delayed light", "subtitle": "Follow energy through absorption, non-radiative relaxation and emission; distinguish fast fluorescence from a metastable afterglow.", "bank": [{"q": "Fluorescence is usually\u2026", "o": ["prompt", "permanent", "reflection only"], "a": 0, "explain": "Emission follows excitation rapidly."}, {"q": "Afterglow uses\u2026", "o": ["stored internal energy", "new photons from a switched-off source", "energy from nothing"], "a": 0, "explain": "Excited populations can persist."}, {"q": "Non-radiative relaxation can transfer energy to\u2026", "o": ["thermal motion", "nothing", "negative photons"], "a": 0, "explain": "Energy is conserved."}, {"q": "A metastable state is\u2026", "o": ["comparatively long lived", "the only ground state", "always permanent"], "a": 0, "explain": "Its decay transition is inhibited."}, {"q": "Lower emitted photon energy means wavelength\u2026", "o": ["longer", "shorter", "unchanged"], "a": 0, "explain": "\u03bb = hc/E."}, {"q": "Photon yield equals energy efficiency\u2026", "o": ["always", "only when photon energies and other conditions justify it", "never in any case"], "a": 1, "explain": "Energy ratio includes energy per photon."}], "practice": [{"q": "A system absorbs 6.00 eV, loses 2.00 eV without light, then emits. Find photon wavelength.", "points": ["Emitted energy is 4.00 eV.", "Convert to 6.40 \u00d7 10\u207b\u00b9\u2079 J.", "Wavelength is 311 nm."]}, {"q": "Explain an afterglow using labelled states and energy conservation.", "points": ["Absorption excites the system.", "A metastable population retains internal energy after illumination stops.", "Later radiative transitions release stored energy as photons; losses can also heat surroundings."]}], "pages": [{"title": "Absorption begins the process", "html": "<div class=\"pp-page\"><p>An incoming photon can excite an electron when its energy matches an available transition. Its energy is hf; the whole source power is not the energy of one absorbed photon.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The ground state is the starting state", "html": "<div class=\"pp-page\"><p>The ground state is the lowest accessible electronic state. An upward arrow represents energy supplied to the system, rather than light already being emitted.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Excitation raises internal energy", "html": "<div class=\"pp-page\"><p>An excited state has more internal energy than the ground state. The electron does not gain an arbitrary fractional bound-state energy: allowed transitions govern absorption.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Relaxation can happen without light", "html": "<div class=\"pp-page\"><p>An excited system may transfer some energy to vibrations or surrounding material. This non-radiative relaxation increases thermal energy and reduces energy available for an emitted photon.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Fluorescence is prompt emission", "html": "<div class=\"pp-page\"><p>Fluorescence usually follows an allowed radiative transition rapidly after excitation. When the source is removed, the visible response typically decays rapidly.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A lifetime is an average waiting time", "html": "<div class=\"pp-page\"><p>Many identical excited systems need not emit at the same instant. A characteristic lifetime describes the statistical decay of a population, not an exact clock for every atom.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Metastable means comparatively long lived", "html": "<div class=\"pp-page\"><p>A metastable state has an inhibited transition to a lower state. Energy can remain stored longer before eventual emission; metastable does not mean permanently stable.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Phosphorescence can persist after illumination", "html": "<div class=\"pp-page\"><p>Phosphorescence commonly involves a long-lived state and slow release. Afterglow can continue after the exciting lamp is removed because excited populations remain.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Use an energy-level diagram", "html": "<div class=\"pp-page\"><p>Label ground, initially excited and intermediate/metastable states. Show absorption upward, non-radiative transfer separately and radiative emission downward.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Emitted energy comes from a gap", "html": "<div class=\"pp-page\"><p>For emission from Ei to Ef, E\u03b3 = Ei \u2212 Ef > 0. Subtract the levels before converting to joules and calculating wavelength.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A Stokes shift is lower-energy emission", "html": "<div class=\"pp-page\"><p>If relaxation loses some energy before emission, the emitted photon is lower energy and longer wavelength than the absorbed photon. Energy difference goes elsewhere, often to thermal motion.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Conserve energy across the whole process", "html": "<div class=\"pp-page\"><p>One absorbed photon can supply emitted-photon energy plus non-radiative transfers. Do not claim missing energy disappears because the emitted colour differs.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Colour depends on wavelength", "html": "<div class=\"pp-page\"><p>Visible emission colour follows emitted wavelength, not necessarily the invisible ultraviolet excitation wavelength. Convert nm to metres before using hc/\u03bb.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Distinguish reflection from re-emission", "html": "<div class=\"pp-page\"><p>Reflection redirects incident radiation; fluorescence absorbs and later emits through internal energy states, often at a different wavelength.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Brightness depends on excitation rate and yield", "html": "<div class=\"pp-page\"><p>More absorbed photons can produce more emitted photons if yield remains similar. A brighter glow does not by itself imply larger emitted energy per photon.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Not every absorbed photon becomes visible emission", "html": "<div class=\"pp-page\"><p>Non-radiative losses and competing processes reduce fluorescence yield. A supplied yield gives the emitted-photon fraction, not an energy efficiency automatically.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Temperature can affect competing processes", "html": "<div class=\"pp-page\"><p>Collisions and thermal processes can change non-radiative pathways and lifetimes. Do not infer an identical decay time for every material.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Observe after switching the source off", "html": "<div class=\"pp-page\"><p>A prompt response disappearing quickly suggests fluorescence; a persistent delayed response suggests phosphorescence. State the timing evidence rather than identifying solely by colour.</p></div>", "chapter": 1, "type": "learn"}, {"title": "UV absorption and visible emission", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A molecule absorbs 4.00 eV and emits 2.50 eV. Find emitted wavelength and non-radiative transfer.</p><ol><li>Energy loss outside the emitted photon is 4.00 \u2212 2.50 = 1.50 eV.</li><li>E\u03b3 = 2.50 \u00d7 1.60 \u00d7 10\u207b\u00b9\u2079 = 4.00 \u00d7 10\u207b\u00b9\u2079 J.</li><li>\u03bb = hc/E\u03b3 = 497 nm. Its energy is smaller and wavelength longer than the absorbed photon.</li></ol>__FIG_fluor__</div>", "chapter": 2, "type": "worked"}, {"title": "Two-step relaxation", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Levels are 0, 2.00 and 5.00 eV. Absorb from 0 to 5, relax without light to 2, then emit to 0.</p><ol><li>Absorbed energy is 5.00 eV.</li><li>Non-radiative transfer is 3.00 eV and emitted energy is 2.00 eV.</li><li>The emitted wavelength is 622 nm; 3 + 2 = 5 conserves energy.</li></ol>__FIG_cascade__</div>", "chapter": 2, "type": "worked"}, {"title": "Afterglow interpretation", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A sample glows for several seconds after a UV lamp is switched off.</p><ol><li>Excitation has stopped, so continuing output uses previously stored internal energy.</li><li>A relatively long-lived excited/metastable population supports delayed emission.</li><li>This timing is consistent with phosphorescence; reflection alone cannot explain light after the source is absent.</li></ol>__FIG_metastable__</div>", "chapter": 2, "type": "worked"}, {"title": "Photon yield is not energy efficiency", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> 10\u2076 photons of 4 eV are absorbed; 60% produce one 2 eV photon.</p><ol><li>Emitted count = 0.60 \u00d7 10\u2076 = 6.0 \u00d7 10\u2075 photons.</li><li>Input energy is 4 \u00d7 10\u2076 eV; output is 1.2 \u00d7 10\u2076 eV.</li><li>Energy efficiency is 30%, not the 60% photon yield.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Supplied decay model", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Use the supplied model N = N\u20802^(\u2212t/T) with T = 2 s and t = 6 s.</p><ol><li>There are 6/2 = 3 population half-times.</li><li>N/N\u2080 = (1/2)\u00b3 = 1/8.</li><li>This model is an application supplied for this problem, not a universal phosphorescence law.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Compare colours", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Equal photon rates are emitted at 400 and 800 nm. Compare emitted power.</p><ol><li>E \u221d 1/\u03bb, so each 400 nm photon has twice the energy.</li><li>At equal photon rate P = N\u0307E gives twice the power for 400 nm.</li><li>A shorter lifetime alone does not determine this comparison.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Gap 3 eV to 1 eV: emitted energy", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Input 5 eV, output 3 eV: non-radiative energy", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: fluor", "html": "<div class=\"pp-page\">__FIG_fluor__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: cascade", "html": "<div class=\"pp-page\">__FIG_cascade__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: metastable", "html": "<div class=\"pp-page\">__FIG_metastable__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Why can ultraviolet illumination produce visible emission?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Why can ultraviolet illumination produce visible emission?", "points": ["Some absorbed energy transfers non-radiatively before emission, leaving a smaller radiative energy gap and a longer emitted wavelength."], "claim": "Follow energy through absorption, non-radiative relaxation and emission; distinguish fast fluorescence from a metastable afterglow."}, "summary": "Follow energy through absorption, non-radiative relaxation and emission; distinguish fast fluorescence from a metastable afterglow."};const guides=[["Gap 3 eV to 1 eV: emitted energy", 2, "eV", "Subtract final energy from initial."], ["Input 5 eV, output 3 eV: non-radiative energy", 2, "eV", "Energy conservation gives 5 \u2212 3."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("Some absorbed energy transfers non-radiatively before emission, leaving a smaller radiative energy gap and a longer emitted wavelength.")));});C.register(s);}

{const s={"id": "x-ray-production", "parent": "quantum", "title": "X-rays: accelerating electrons, cut-off wavelength and characteristic lines", "shortTitle": "X-rays: accelerating electrons, cut-off wavelength and characteristic lines", "subtitle": "Separate continuous braking radiation from discrete target transitions and solve voltage, wavelength and power scenarios.", "bank": [{"q": "Cut-off wavelength depends directly on\u2026", "o": ["tube voltage", "current alone", "number of detector pixels"], "a": 0, "explain": "Maximum electron energy is eV."}, {"q": "Characteristic lines arise from\u2026", "o": ["target level gaps", "all electrons losing identical braking energy", "air pressure only"], "a": 0, "explain": "Discrete transitions emit discrete energies."}, {"q": "At fixed V, doubling I leaves ideal \u03bbmin\u2026", "o": ["unchanged", "doubled", "halved"], "a": 0, "explain": "Energy per electron is unchanged."}, {"q": "An electron across 10 kV gains\u2026", "o": ["10 keV", "10 eV", "10 J"], "a": 0, "explain": "Energy in eV equals voltage in volts for one electron."}, {"q": "Most tube power usually becomes\u2026", "o": ["heat", "one cut-off photon each time", "nothing"], "a": 0, "explain": "Radiative efficiency is usually small."}, {"q": "Shorter X-ray wavelength means\u2026", "o": ["larger energy", "smaller energy", "same energy"], "a": 0, "explain": "E = hc/\u03bb."}], "practice": [{"q": "Find minimum wavelength at 60.0 kV.", "points": ["Emax = 9.60 \u00d7 10\u207b\u00b9\u2075 J.", "\u03bbmin = 2.07 \u00d7 10\u207b\u00b9\u00b9 m.", "This is 0.0207 nm."]}, {"q": "Explain the continuous spectrum and discrete peaks.", "points": ["Braking electrons lose varying amounts of energy.", "Inner-shell vacancies followed by discrete transitions produce characteristic photons.", "Target material fixes characteristic gaps; voltage sets the continuum cut-off."]}], "pages": [{"title": "Identify the particles in the tube", "html": "<div class=\"pp-page\"><p>Electrons are accelerated across a potential difference and strike a target. The emitted X-ray photons are different particles from the incident electrons.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The cathode supplies electrons", "html": "<div class=\"pp-page\"><p>A heated cathode can release electrons by thermionic emission. Heating supplies electrons; the accelerating potential determines their ideal maximum impact kinetic energy.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The anode is the target", "html": "<div class=\"pp-page\"><p>The positive target attracts the electrons. The target converts their kinetic energy into radiation and mostly thermal energy, so cooling is important.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Electron charge determines acceleration energy", "html": "<div class=\"pp-page\"><p>An electron starting nearly at rest gains K = eV across voltage magnitude V. In electronvolts, acceleration through 30 kV corresponds to 30 keV.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Tube current counts electrons", "html": "<div class=\"pp-page\"><p>Current I is charge passing per second. Electron arrival rate is I/e, distinct from photon rate because emission is not necessarily one photon per electron.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Braking can produce photons", "html": "<div class=\"pp-page\"><p>An electron deflected or slowed by a target nucleus can radiate. Different encounters lose different energies, producing a continuous range of photon energies.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Bremsstrahlung forms a continuum", "html": "<div class=\"pp-page\"><p>Continuous braking radiation contains many wavelengths above a shortest limit. It is not a set of equally spaced atomic energy levels.</p></div>", "chapter": 0, "type": "learn"}, {"title": "One photon cannot exceed available energy", "html": "<div class=\"pp-page\"><p>The largest photon energy in the ideal model occurs when one electron transfers all its gained kinetic energy into one photon: Emax = eV.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Cut-off means shortest wavelength", "html": "<div class=\"pp-page\"><p>Since E = hc/\u03bb, the maximum energy corresponds to minimum wavelength \u03bbmin = hc/(eV). A photon below this wavelength would require more energy than an electron has.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Most photons are not at the cut-off", "html": "<div class=\"pp-page\"><p>Partial energy transfers produce lower-energy, longer-wavelength photons. The minimum is an energy-conservation boundary, not the average emitted wavelength.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Higher voltage shifts the cut-off", "html": "<div class=\"pp-page\"><p>Doubling V doubles Emax and halves \u03bbmin. Tube voltage can also influence output, but it directly sets the ideal maximum photon energy.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Higher current mainly changes output rate", "html": "<div class=\"pp-page\"><p>At fixed voltage, more incident electrons generally increase X-ray output. The ideal cut-off remains the same because electron energy eV is unchanged.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Inner-shell vacancies lead to lines", "html": "<div class=\"pp-page\"><p>An energetic incident electron can remove a tightly bound target electron. An outer electron falling into the vacancy emits a photon with a discrete energy difference.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Characteristic energies identify the target", "html": "<div class=\"pp-page\"><p>Target atomic levels determine characteristic line energies. Changing target material changes these energies; merely changing current does not change the gaps.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A threshold is required for a vacancy", "html": "<div class=\"pp-page\"><p>If incident electron energy is insufficient to eject an inner-shell electron, the corresponding characteristic emission process cannot occur, even with large current.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Read superposed spectra", "html": "<div class=\"pp-page\"><p>Characteristic peaks can sit on top of the continuous background. Label wavelength or photon energy axes carefully because shortest wavelength means largest energy.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Electrical input is power IV", "html": "<div class=\"pp-page\"><p>Tube input power is IV. A supplied X-ray conversion efficiency gives radiation power; the remaining power mostly appears as heating.</p></div>", "chapter": 1, "type": "learn"}, {"title": "X-rays are ionising radiation", "html": "<div class=\"pp-page\"><p>Their photons can eject electrons from matter. Shielding and controlled exposure address absorbed energy and biological consequences; avoid treating them as harmless visible light.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Cut-off at 30 kV", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Find maximum photon energy and minimum wavelength at 30.0 kV.</p><ol><li>V = 3.00 \u00d7 10\u2074 V; Emax = eV = 4.80 \u00d7 10\u207b\u00b9\u2075 J = 30.0 keV.</li><li>\u03bbmin = 1.989 \u00d7 10\u207b\u00b2\u2075/(4.80 \u00d7 10\u207b\u00b9\u2075).</li><li>\u03bbmin = 4.14375 \u00d7 10\u207b\u00b9\u00b9 m = 0.0414 nm.</li></ol>__FIG_xraytube__</div>", "chapter": 2, "type": "worked"}, {"title": "Reverse: wavelength gives voltage", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A tube has cut-off 0.0500 nm. Find ideal accelerating voltage.</p><ol><li>\u03bbmin = 5.00 \u00d7 10\u207b\u00b9\u00b9 m.</li><li>V = hc/(e\u03bbmin) = 24862.5 V.</li><li>V \u2248 24.9 kV; this uses the maximum-energy limit.</li></ol>__FIG_xrayspectrum__</div>", "chapter": 2, "type": "worked"}, {"title": "Characteristic line", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A target electron falls from \u221210 keV to \u221270 keV. Find photon energy and wavelength.</p><ol><li>Energy difference is (\u221210) \u2212 (\u221270) = 60 keV.</li><li>Convert to 9.60 \u00d7 10\u207b\u00b9\u2075 J.</li><li>\u03bb = 0.0207 nm; the target gap determines this line.</li></ol>__FIG_xraylevels__</div>", "chapter": 2, "type": "worked"}, {"title": "Current change", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> At 40 kV, tube current doubles from 2 to 4 mA.</p><ol><li>Electron impact energy remains 40 keV.</li><li>Electron rate doubles, so output generally increases under unchanged conditions.</li><li>Minimum wavelength stays 0.0311 nm; current does not double each photon energy.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Heating budget", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A 50 kV tube operates at 10 mA with supplied X-ray efficiency 1%.</p><ol><li>Input power = 50000 \u00d7 0.0100 = 500 W.</li><li>X-ray power = 0.01 \u00d7 500 = 5 W.</li><li>Other power \u2248 495 W, mainly heating; efficiency is supplied rather than universal.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Impossible proposed photon", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Can a 20 kV tube produce a 30 keV braking photon in this model?</p><ol><li>One electron gains only 20 keV.</li><li>A 30 keV photon exceeds the available energy per electron.</li><li>It is excluded by the stated single-electron energy accounting, regardless of current.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Maximum photon energy at 45 kV", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Double tube voltage: \u03bbmin,new / \u03bbmin,old", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: xraytube", "html": "<div class=\"pp-page\">__FIG_xraytube__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: xrayspectrum", "html": "<div class=\"pp-page\">__FIG_xrayspectrum__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: xraylevels", "html": "<div class=\"pp-page\">__FIG_xraylevels__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Why does changing target material alter peaks but not the ideal voltage-defined cut-off?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Why does changing target material alter peaks but not the ideal voltage-defined cut-off?", "points": ["Atomic energy gaps depend on target atoms. The cut-off follows maximum incident electron energy eV, which is fixed by accelerating voltage."], "claim": "Separate continuous braking radiation from discrete target transitions and solve voltage, wavelength and power scenarios."}, "summary": "Separate continuous braking radiation from discrete target transitions and solve voltage, wavelength and power scenarios."};const guides=[["Maximum photon energy at 45 kV", 45, "keV", "An electron gains 45 keV."], ["Double tube voltage: \u03bbmin,new / \u03bbmin,old", 0.5, "ratio", "\u03bbmin \u221d 1/V."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("Atomic energy gaps depend on target atoms. The cut-off follows maximum incident electron energy eV, which is fixed by accelerating voltage.")));});C.register(s);}

{const s={"id": "laser-stimulated-emission", "parent": "quantum", "title": "Lasers: stimulated emission, inversion and coherent output", "shortTitle": "Lasers: stimulated emission, inversion and coherent output", "subtitle": "Build a working laser model from pumping, metastable states, stimulated emission and optical feedback.", "bank": [{"q": "Stimulated emission adds energy from\u2026", "o": ["the excited medium", "nothing", "a consumed trigger photon only"], "a": 0, "explain": "The emitting particle falls to a lower state."}, {"q": "Inversion requires\u2026", "o": ["more upper population in the stated simple model", "every atom in ground state", "zero pump energy"], "a": 0, "explain": "The upper state is comparatively populated."}, {"q": "Metastable means\u2026", "o": ["long lived relative to alternatives", "permanent", "zero energy"], "a": 0, "explain": "It assists population accumulation."}, {"q": "Cavity mirrors provide\u2026", "o": ["feedback", "new energy without pumping", "automatic inversion"], "a": 0, "explain": "They return light through the medium."}, {"q": "A coherent beam has\u2026", "o": ["a stable phase relationship", "necessarily infinite power", "no photons"], "a": 0, "explain": "Coherence describes phase correlations."}, {"q": "A narrow spectrum determines\u2026", "o": ["similar photon energies", "pump efficiency automatically", "all beam powers"], "a": 0, "explain": "E = hf links frequency to energy."}], "practice": [{"q": "A 650 nm laser has output 3 mW. Find photon rate.", "points": ["E = 3.06 \u00d7 10\u207b\u00b9\u2079 J.", "Rate = 9.80 \u00d7 10\u00b9\u2075/s.", "Use output power, not pumping power."]}, {"q": "Explain why pumping, inversion and mirrors are needed.", "points": ["Pumping supplies excitation energy.", "Inversion permits stimulated emission to outweigh absorption.", "Mirrors provide repeated passes and selective feedback; a partial mirror permits output."]}], "pages": [{"title": "Laser names a mechanism", "html": "<div class=\"pp-page\"><p>LASER stands for light amplification by stimulated emission of radiation. The defining process amplifies light through stimulated photon emission, rather than simply producing a bright lamp.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A medium provides energy levels", "html": "<div class=\"pp-page\"><p>Atoms, molecules or a semiconductor medium provide suitable transitions. The selected transition gap sets photon frequency through \u0394E = hf.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Absorption removes a photon", "html": "<div class=\"pp-page\"><p>A lower-state system absorbs a resonant photon and moves upward. This competing process can weaken a beam if many particles occupy the lower state.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Spontaneous emission happens without a trigger", "html": "<div class=\"pp-page\"><p>An excited system can emit a photon without an incoming photon stimulating it. Individual spontaneous emissions have varied directions and phases.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Stimulated emission uses a resonant photon", "html": "<div class=\"pp-page\"><p>An incident photon with energy matching a transition can trigger an excited system to fall to the lower state and emit an additional photon.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The trigger is not consumed by emission", "html": "<div class=\"pp-page\"><p>In ideal stimulated emission the incident photon continues and a second photon is added. The medium supplies the additional energy by losing excitation.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Matching frequency supports coherence", "html": "<div class=\"pp-page\"><p>The stimulated photon shares the triggering field frequency, direction, phase and polarisation in the ideal model. This allows coherent amplification.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Coherence describes phase relationships", "html": "<div class=\"pp-page\"><p>Coherent waves have a stable phase relationship over a specified time or distance. Coherence is different from merely having a large total power.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Population means number in a state", "html": "<div class=\"pp-page\"><p>Count how many particles occupy upper and lower laser states. The balance of populations affects stimulated emission versus absorption.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Population inversion favours amplification", "html": "<div class=\"pp-page\"><p>An inversion means the relevant upper state is more populated than the lower state under the simple equal-degeneracy model. Ordinary thermal populations do not automatically provide this.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Pumping supplies external energy", "html": "<div class=\"pp-page\"><p>Optical, electrical or other pumping raises the medium into excited states. Output energy ultimately comes from the pumping source, conserving energy.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A metastable upper state stores excitation", "html": "<div class=\"pp-page\"><p>A relatively long-lived upper laser state lets particles accumulate. A fast fall into that state after pumping can support the required inversion.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A quickly emptied lower state helps", "html": "<div class=\"pp-page\"><p>Removing population from the lower laser state reduces absorption. Real laser level schemes use suitable lifetimes, rather than simply two indefinitely occupied states.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A resonator provides repeated passes", "html": "<div class=\"pp-page\"><p>Two mirrors return light through the medium repeatedly, increasing opportunities for stimulated emission. Alignment selects propagation directions.</p></div>", "chapter": 1, "type": "learn"}, {"title": "One mirror permits useful output", "html": "<div class=\"pp-page\"><p>A partly transmitting mirror allows some cavity radiation to escape as the beam. The other feedback and gain must compensate cavity losses.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Threshold balances gain and loss", "html": "<div class=\"pp-page\"><p>Laser action begins when amplification can overcome losses. Below threshold, spontaneous emission may occur without sustained coherent laser output.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Monochromatic is an approximation", "html": "<div class=\"pp-page\"><p>A laser generally has a narrow spectral range rather than literally zero linewidth. Directional, coherent and narrow-spectrum describe different properties.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Use power to count photons", "html": "<div class=\"pp-page\"><p>For output power P and photon energy hc/\u03bb, output photon rate is P\u03bb/(hc). Pump efficiency changes power; the transition energy determines wavelength.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Laser transition", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Upper level is 3.20 eV and lower is 1.20 eV. Find wavelength.</p><ol><li>\u0394E = 2.00 eV = 3.20 \u00d7 10\u207b\u00b9\u2079 J.</li><li>\u03bb = hc/\u0394E = 622 nm.</li><li>Pumping can involve a different, larger energy gap.</li></ol>__FIG_laserlevels__</div>", "chapter": 2, "type": "worked"}, {"title": "Stimulated event", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> One resonant photon meets an excited atom that emits through the same transition.</p><ol><li>The atom loses one transition energy hf.</li><li>The original photon continues and one additional matching photon is emitted.</li><li>Two photons emerge in the ideal mode; the atom supplied the second photon energy.</li></ol>__FIG_stimulated__</div>", "chapter": 2, "type": "worked"}, {"title": "Inversion test", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> There are 600 upper-state and 400 lower-state particles in an equal-degeneracy model.</p><ol><li>Upper population exceeds lower, so this pair is inverted.</li><li>Pumping must maintain inversion against transitions and losses.</li><li>A 400 upper / 600 lower distribution is not inverted.</li></ol>__FIG_lasercavity__</div>", "chapter": 2, "type": "worked"}, {"title": "Photon rate", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A 2.00 mW laser emits at 600 nm. Find rate.</p><ol><li>One photon has E = 3.315 \u00d7 10\u207b\u00b9\u2079 J.</li><li>N\u0307 = 0.00200/E = 6.03 \u00d7 10\u00b9\u2075 photons/s.</li><li>Narrow wavelength fixes energy per photon; power fixes how many arrive each second.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Pump power", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A supplied overall efficiency is 10%; laser output is 5 W.</p><ol><li>\u03b7 = Pout/Pin; Pin = 5/0.10 = 50 W.</li><li>Other transfer is 45 W.</li><li>Efficiencies depend on design; this supplied value is not universal.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Pulse count", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A 500 nm laser pulse contains 1.00 mJ.</p><ol><li>Photon energy is 3.978 \u00d7 10\u207b\u00b9\u2079 J.</li><li>N = 0.00100/E = 2.51 \u00d7 10\u00b9\u2075 photons.</li><li>Pulse energy, not pulse power alone, determines this count.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Transition 4 eV to 1 eV: photon energy", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Output 8 W, input40 W: efficiency", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: laserlevels", "html": "<div class=\"pp-page\">__FIG_laserlevels__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: stimulated", "html": "<div class=\"pp-page\">__FIG_stimulated__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: lasercavity", "html": "<div class=\"pp-page\">__FIG_lasercavity__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Does amplification violate conservation of energy?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Does amplification violate conservation of energy?", "points": ["No. Each additional photon carries energy lost by an excited particle. The pump maintains the stored excitation that supplies output and other energy transfers."], "claim": "Build a working laser model from pumping, metastable states, stimulated emission and optical feedback."}, "summary": "Build a working laser model from pumping, metastable states, stimulated emission and optical feedback."};const guides=[["Transition 4 eV to 1 eV: photon energy", 3, "eV", "\u0394E = 4 \u2212 1."], ["Output 8 W, input40 W: efficiency", 20, "%", "8/40 \u00d7 100 = 20%."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("No. Each additional photon carries energy lost by an excited particle. The pump maintains the stored excitation that supplies output and other energy transfers.")));});C.register(s);}

{const s={"id": "photovoltaic-cells", "parent": "quantum", "title": "Photovoltaic cells: photons, charge separation and useful electrical power", "shortTitle": "Photovoltaic cells: photons, charge separation and useful electrical power", "subtitle": "Connect a semiconductor energy gap to sunlight, electron\u2013hole creation, circuit output and area-efficiency calculations.", "bank": [{"q": "Incident power equals\u2026", "o": ["GA", "G/A", "IV regardless of input"], "a": 0, "explain": "W/m\u00b2 timesm\u00b2 givesW."}, {"q": "A hole is\u2026", "o": ["an electron vacancy", "a proton emitted by light", "a photon"], "a": 0, "explain": "It behaves as a positive carrier."}, {"q": "Open circuit has external current\u2026", "o": ["zero", "always maximum", "infinite"], "a": 0, "explain": "No complete external path exists."}, {"q": "At short circuit terminal power is ideally\u2026", "o": ["near zero", "always maximum", "negative input"], "a": 0, "explain": "Voltage is near zero."}, {"q": "Below-gap photons have\u2026", "o": ["insufficient energy for the stated transition", "always higher current than all other photons", "negative energy"], "a": 0, "explain": "Compare hf withEg."}, {"q": "100 cm\u00b2 equals\u2026", "o": ["0.0100 m\u00b2", "1 m\u00b2", "0.1 m\u00b2"], "a": 0, "explain": "Eachcm\u00b2 is10\u207b\u2074m\u00b2."}], "practice": [{"q": "A0.80 m\u00b2 panel under900 W/m\u00b2 delivers18 V and8 A. Find efficiency.", "points": ["Input = 720 W.", "Output = 144 W.", "Efficiency = 20%."]}, {"q": "Explain why brighter light below the band-gap threshold does not automatically create interband carriers.", "points": ["Each photon has energy hf.", "Below threshold that energy is insufficient for the gap.", "Increasing photon count does not increase each photon energy in the stated model."]}], "pages": [{"title": "A photovoltaic cell converts energy", "html": "<div class=\"pp-page\"><p>A cell converts part of incident radiation energy into electrical energy supplied to a circuit. It does not produce energy from nothing or merely store all the incoming sunlight.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Semiconductors have bands", "html": "<div class=\"pp-page\"><p>A valence band contains occupied electron states; a conduction band contains states allowing mobile carriers. The forbidden energy gap separates these bands in the simplified model.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The band gap is an energy threshold", "html": "<div class=\"pp-page\"><p>A photon needs sufficient energy to promote an electron across the gap in the simple absorption model. Compare hf with Eg before claiming carrier creation.</p></div>", "chapter": 0, "type": "learn"}, {"title": "An electron\u2013hole pair is created", "html": "<div class=\"pp-page\"><p>An excited conduction electron leaves a vacancy called a hole in the valence band. Both act as charge carriers; a hole is not a newly created proton.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Below-gap photons may pass through", "html": "<div class=\"pp-page\"><p>If photon energy is less than the band gap, this interband process cannot use the photon. Higher brightness does not increase energy of each below-gap photon.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Above-gap photons can create carriers", "html": "<div class=\"pp-page\"><p>A photon with energy at least Eg can excite an electron. Excess energy often transfers to thermal motion rather than appearing entirely as extra useful circuit energy.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The junction supplies charge separation", "html": "<div class=\"pp-page\"><p>A junction\u2019s built-in electric field helps drive electrons and holes in opposite directions. This reduces recombination and supports an external potential difference.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Recombination is a competing loss", "html": "<div class=\"pp-page\"><p>An electron and hole can recombine before contributing to external current. Good collection does not mean every incident photon necessarily produces one collected electron.</p></div>", "chapter": 0, "type": "learn"}, {"title": "An external path is required for current", "html": "<div class=\"pp-page\"><p>A connected load allows charges to move around a complete circuit. At open circuit a voltage can exist while external current is zero.</p></div>", "chapter": 0, "type": "learn"}, {"title": "A short circuit has little terminal voltage", "html": "<div class=\"pp-page\"><p>A shorted cell can have current but nearly zero terminal voltage. Since P = IV, maximum current alone is not maximum useful power.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A load determines operating point", "html": "<div class=\"pp-page\"><p>Current and voltage depend on the load and illumination. The maximum-power point lies between open-circuit and short-circuit extremes.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Irradiance is power per area", "html": "<div class=\"pp-page\"><p>Irradiance G in W/m\u00b2 times illuminated area A in m\u00b2 gives incident power GA, for a stated uniform perpendicular illumination assumption.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Distinguish area units", "html": "<div class=\"pp-page\"><p>1 cm\u00b2 = 10\u207b\u2074 m\u00b2. Squaring a centimetre conversion is essential; a factor10\u207b\u00b2 would apply to length rather than area.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Efficiency compares output to input", "html": "<div class=\"pp-page\"><p>\u03b7 = Pout/(GA). Express a fraction as a percentage by multiplying by100; output cannot exceed input in this passive conversion model.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Electrical power is terminal IV", "html": "<div class=\"pp-page\"><p>Use measured terminal current and voltage at the same operating point. Multiplying open-circuit voltage by short-circuit current overstates actual achievable power.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Photon rate can predict an ideal current", "html": "<div class=\"pp-page\"><p>For monochromatic light, N\u0307 = P/E\u03b3. With one collected electron per absorbed photon, I = eN\u0307; a supplied collection fraction reduces this ideal estimate.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Clouds and shading alter usable input", "html": "<div class=\"pp-page\"><p>Lower irradiance generally reduces available power. Shading part of a connected module can produce circuit effects beyond a simple area-only model; state any simplifying assumptions.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Sunlight spans many photon energies", "html": "<div class=\"pp-page\"><p>A solar spectrum contains many wavelengths. One band gap cannot convert every photon energy without threshold or excess-energy losses, helping explain efficiency limits.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Area and output", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> G = 800 W/m\u00b2, A = 0.500 m\u00b2 and \u03b7 = 20%. Find output.</p><ol><li>Incident power = GA = 400 W.</li><li>\u03b7 = 0.20; Pout = 80.0 W.</li><li>Other transfers total320 W under this steady energy accounting.</li></ol>__FIG_pvenergy__</div>", "chapter": 2, "type": "worked"}, {"title": "Measured IV", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A cell supplies0.500 V and2.00 A under1000 W/m\u00b2 over100 cm\u00b2. Find efficiency.</p><ol><li>Area = 100 \u00d7 10\u207b\u2074 = 0.0100 m\u00b2.</li><li>Input10 W; output IV = 1.00 W.</li><li>\u03b7 = 1/10 = 10%.</li></ol>__FIG_pvcurve__</div>", "chapter": 2, "type": "worked"}, {"title": "Band-gap threshold", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Eg = 1.20 eV. Find the longest vacuum wavelength usable in the simple interband model.</p><ol><li>Eg = 1.92 \u00d7 10\u207b\u00b9\u2079 J.</li><li>\u03bbmax = hc/Eg = 1036 nm.</li><li>Longer wavelengths carry too little photon energy.</li></ol>__FIG_pvbands__</div>", "chapter": 2, "type": "worked"}, {"title": "Ideal photon current", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A cell absorbs1 mW at500 nm;60% yield collected electrons.</p><ol><li>E\u03b3 = 3.978 \u00d7 10\u207b\u00b9\u2079 J; photon rate = 2.514 \u00d7 10\u00b9\u2075/s.</li><li>Collected rate = 0.60 times this rate.</li><li>I = eN\u0307collected = 0.241 mA. This is a supplied simple yield model.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Choose a maximum-power point", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Measured pairs(V,I) are(0,3 A),(0.4,2.5 A),(0.6,0).</p><ol><li>Power products are0,1.0 W and0.</li><li>The middle point gives the largest sampled power.</li><li>Open voltage times short current is not an actual measured operating point.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Required area", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> A panel must provide150 W at\u03b7 = 15% andG = 1000 W/m\u00b2.</p><ol><li>Rearrange A = Pout/(\u03b7G).</li><li>A = 150/(0.15 \u00d7 1000) = 1.00 m\u00b2.</li><li>This ignores additional system losses unless supplied.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: G800 W/m\u00b2 andA0.25 m\u00b2: incident power", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: Output30 W from150 W input: efficiency", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: pvenergy", "html": "<div class=\"pp-page\">__FIG_pvenergy__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: pvcurve", "html": "<div class=\"pp-page\">__FIG_pvcurve__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: pvbands", "html": "<div class=\"pp-page\">__FIG_pvbands__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Why is short-circuit current times open-circuit voltage not the panel\u2019s output power?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Why is short-circuit current times open-circuit voltage not the panel\u2019s output power?", "points": ["They occur at different operating points. Real output uses simultaneous current and voltage under a load, and P = IV must use that pair."], "claim": "Connect a semiconductor energy gap to sunlight, electron\u2013hole creation, circuit output and area-efficiency calculations."}, "summary": "Connect a semiconductor energy gap to sunlight, electron\u2013hole creation, circuit output and area-efficiency calculations."};const guides=[["G800 W/m\u00b2 andA0.25 m\u00b2: incident power", 200, "W", "Multiply irradiance by area."], ["Output30 W from150 W input: efficiency", 20, "%", "30/150 \u00d7100."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("They occur at different operating points. Real output uses simultaneous current and voltage under a load, and P = IV must use that pair.")));});C.register(s);}

{const s={"id": "led-quantum-emission", "parent": "quantum", "title": "LEDs: band-gap light, colour and safe circuit calculations", "shortTitle": "LEDs: band-gap light, colour and safe circuit calculations", "subtitle": "Explain electrical excitation and radiative recombination, then connect photon energy, colour, current and resistor power.", "bank": [{"q": "Radiative recombination emits\u2026", "o": ["photons", "only protons", "negative energy"], "a": 0, "explain": "Energy lost by carriers can become light."}, {"q": "Larger gap gives wavelength\u2026", "o": ["shorter", "longer", "always unchanged"], "a": 0, "explain": "\u03bb \u2248 hc/Eg."}, {"q": "Series resistor voltage is\u2026", "o": ["Vs \u2212 Vf", "Vs + Vf", "Vf/I"], "a": 0, "explain": "Apply the loop voltage sum."}, {"q": "20 mA is\u2026", "o": ["0.020 A", "20 A", "0.20 A"], "a": 0, "explain": "Milli means10\u207b\u00b3."}, {"q": "LED current\u2013voltage behaviour is\u2026", "o": ["non-ohmic", "a fixed resistor at every voltage", "always zero"], "a": 0, "explain": "Current can rise sharply."}, {"q": "Increasing current automatically doubles energy per photon\u2026", "o": ["false", "true", "only in vacuum"], "a": 0, "explain": "Transition energy determines photon energy."}], "practice": [{"q": "Supply12 V,LED drop3 V,target15 mA. FindR and resistor power.", "points": ["R = 9/0.015 = 600 \u03a9.", "PR = 9 \u00d70.015 = 0.135 W.", "A component must safely exceed calculated dissipation."]}, {"q": "UseEg2.50 eV to estimate wavelength and explain radiative recombination.", "points": ["\u03bb = 497 nm.", "An electron falls into an available lower-energy state associated with a hole.", "The transition releases a photon; competing processes can release thermal energy."]}], "pages": [{"title": "An LED is a light-emitting diode", "html": "<div class=\"pp-page\"><p>An LED converts some electrical energy into light using a semiconductor junction. It needs suitable polarity and controlled current.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Forward bias permits useful injection", "html": "<div class=\"pp-page\"><p>Connect the anode toward positive and cathode toward negative in a suitable circuit. Forward bias enables carriers to be injected toward the emitting region.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Electrons and holes meet", "html": "<div class=\"pp-page\"><p>Electrons in higher-energy conduction states can recombine with holes in lower-energy valence states. The released energy may produce photons or thermal transfers.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Radiative recombination produces light", "html": "<div class=\"pp-page\"><p>If recombination is radiative, emitted photon energy is approximately the relevant semiconductor transition energy. E\u03b3 = hf connects this to colour.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Band gap relates to colour", "html": "<div class=\"pp-page\"><p>A larger radiative transition gap produces larger photon energy and shorter wavelength. Material and device structure set the emission spectrum.</p></div>", "chapter": 0, "type": "learn"}, {"title": "The simple gap model is approximate", "html": "<div class=\"pp-page\"><p>Use E\u03b3 \u2248 Eg when explicitly stated. Real LEDs have spectral width and losses, so forward voltage is not universally an exact band-gap measurement.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Convert eV before using SI", "html": "<div class=\"pp-page\"><p>IfEg is in eV, multiply by1.60 \u00d710\u207b\u00b9\u2079 to obtain joules before\u03bb = hc/Eg. Alternatively use a consistently convertedhc value.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Red and blue differ in photon energy", "html": "<div class=\"pp-page\"><p>Blue photons have shorter wavelengths and higher energies than red photons. Colour changes do not mean different vacuum propagation speeds.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Current is charge flow rate", "html": "<div class=\"pp-page\"><p>I/e gives electrons per second. Only a supplied photon yield justifies equating that rate with emitted-photon rate.</p></div>", "chapter": 0, "type": "learn"}, {"title": "Brightness depends on emitted rate", "html": "<div class=\"pp-page\"><p>Increasing current within safe limits can increase emitted-photon rate. It does not automatically increase the transition gap or shift colour proportionally.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A diode is not an ohmic resistor", "html": "<div class=\"pp-page\"><p>LED current rises sharply with forward voltage. A small extra voltage can produce a large current increase, so external current control is required.</p></div>", "chapter": 1, "type": "learn"}, {"title": "A series resistor limits current", "html": "<div class=\"pp-page\"><p>With a supplied approximately constantLED voltageVf, resistor voltage isVs \u2212 Vf. UseR = (Vs \u2212 Vf)/I for the desired circuit current.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Check the supply is sufficient", "html": "<div class=\"pp-page\"><p>A positive resistor drop requiresVs > Vf in this simplified forward-conduction model. A negative calculatedR signals that the assumed operating point is unavailable.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Resistor power matters", "html": "<div class=\"pp-page\"><p>The resistor dissipatesPR = I\u00b2R = I(Vs \u2212 Vf). Choose an appropriately rated component rather than checking resistance alone.</p></div>", "chapter": 1, "type": "learn"}, {"title": "LED electrical input is VfI", "html": "<div class=\"pp-page\"><p>At an operating point, LED electrical power isVfI. The resistor dissipates separate power; distinguish device efficiency from whole-circuit efficiency.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Optical output can be calculated", "html": "<div class=\"pp-page\"><p>With supplied optical efficiency\u03b7, Popt = \u03b7VfI. Other LED transfers account for the remaining input, often heating.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Reverse bias needs care", "html": "<div class=\"pp-page\"><p>A reverse-biased LED usually does not emit normally and can be damaged at excessive reverse voltage. Do not assume reversing polarity simply changes emitted colour.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Compare practical applications", "html": "<div class=\"pp-page\"><p>Indicators, displays and lighting use different materials and current-control methods. A labelled circuit must identify supply, resistor, LED polarity and current direction.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Gap and colour", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> UseE\u03b3 \u2248 Eg = 2.00 eV. Find wavelength.</p><ol><li>ConvertE = 3.20 \u00d710\u207b\u00b9\u2079 J.</li><li>\u03bb = hc/E = 622 nm.</li><li>This lies near the red/orange visible region under the supplied gap approximation.</li></ol>__FIG_ledbands__</div>", "chapter": 2, "type": "worked"}, {"title": "Series resistor", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Supply9.0 V;LED drop2.0 V;desired20 mA.</p><ol><li>Resistor drop = 7.0 V.</li><li>R = 7.0/0.020 = 350 \u03a9.</li><li>Resistor power = 0.020 \u00d77.0 = 0.140 W; select a rating exceeding dissipation with suitable margin.</li></ol>__FIG_ledcircuit__</div>", "chapter": 2, "type": "worked"}, {"title": "Blue versus red", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Compare450 nm and650 nm emitted photons.</p><ol><li>E450/E650 = 650/450 = 1.44.</li><li>Blue photons carry about44% more energy.</li><li>Both travel atc in vacuum; equal currents do not by themselves guarantee equal optical power.</li></ol>__FIG_ledcolour__</div>", "chapter": 2, "type": "worked"}, {"title": "LED and resistor budgets", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> For the9 V20 mA circuit withVf2 V, suppliedLED optical efficiency is25%.</p><ol><li>Supply power = 0.180 W;LED input = 0.040 W.</li><li>Optical power = 0.010 W;LED other transfer = 0.030 W.</li><li>Resistor dissipates0.140 W;whole-circuit optical efficiency = 5.56%.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Photon yield", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Current10 mA;suppliedyield0.50 emitted photons per electron;\u03bb600 nm.</p><ol><li>Electron rate = 0.010/e = 6.25 \u00d710\u00b9\u2076/s.</li><li>Photon rate = 3.125 \u00d710\u00b9\u2076/s.</li><li>Each photon3.315 \u00d710\u207b\u00b9\u2079 J givesPopt = 0.01036 W.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Insufficient supply", "html": "<div class=\"pp-page\"><p><strong>Original exam-style scenario.</strong> Can a1.5 V supply produce the assumedVf2.0 V20 mA operating point with only a positive series resistor?</p><ol><li>The proposed resistor drop is1.5 \u22122.0 = \u22120.5 V.</li><li>A passive resistor cannot supply the missing voltage.</li><li>The assumed operating point is unavailable; do not choose a negative resistor.</li></ol></div>", "chapter": 2, "type": "worked"}, {"title": "Guided calculation: Supply5 V,LED2 V,current10 mA: R", "html": "<div class=\"pp-page\">__NUM_0__</div>", "chapter": 3, "type": "interactive"}, {"title": "Guided calculation: LEDVf3 V,current20 mA: electrical power", "html": "<div class=\"pp-page\">__NUM_1__</div>", "chapter": 3, "type": "interactive"}, {"title": "Independent exam-style task 1", "html": "<div class=\"pp-page\">__PRACTICE_0__</div>", "chapter": 3, "type": "practice"}, {"title": "Independent exam-style task 2", "html": "<div class=\"pp-page\">__PRACTICE_1__</div>", "chapter": 3, "type": "practice"}, {"title": "Diagram study: ledbands", "html": "<div class=\"pp-page\">__FIG_ledbands__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: ledcircuit", "html": "<div class=\"pp-page\">__FIG_ledcircuit__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Diagram study: ledcolour", "html": "<div class=\"pp-page\">__FIG_ledcolour__<p>Identify the labelled quantities, describe the arrows or axes, and explain how this model supports the worked scenarios.</p></div>", "chapter": 1, "type": "learn"}, {"title": "Explain the transfer scenario", "html": "<div class=\"pp-page\"><p>Why must LED efficiency and whole-circuit efficiency be distinguished?</p>__CHECK____TRANSFER__</div>", "chapter": 3, "type": "practice"}], "chapters": [["Build the model", "Meaning, quantities and units"], ["Read the evidence", "Diagrams, relationships and limits"], ["Worked scenarios", "Choose a model and explain each step"], ["Practise and check", "Guided and independent problems"]], "constants": "c = 3.00 \u00d7 10\u2078 m/s; h = 6.63 \u00d7 10\u207b\u00b3\u2074 J s; e = 1.60 \u00d7 10\u207b\u00b9\u2079 C; me = 9.11 \u00d7 10\u207b\u00b3\u00b9 kg", "focus": {"question": "Why must LED efficiency and whole-circuit efficiency be distinguished?", "points": ["The LED receivesVfI, whereas the supply also powers resistor heating. Optical output divided by total supply input is consequently lower than device-only efficiency in this series-resistor circuit."], "claim": "Explain electrical excitation and radiative recombination, then connect photon energy, colour, current and resistor power."}, "summary": "Explain electrical excitation and radiative recombination, then connect photon energy, colour, current and resistor power."};const guides=[["Supply5 V,LED2 V,current10 mA: R", 300, "\u03a9", "R = 3/0.010."], ["LEDVf3 V,current20 mA: electrical power", 0.06, "W", "P = VI = 3 \u00d70.020."]];s.pages.forEach(p=>{p.html=p.html.replace(/__FIG_([a-z]+)__/g,(_,k)=>fig(k));guides.forEach((g,i)=>{p.html=p.html.replace("__NUM_"+i+"__",number(s.id+"-n"+i,g[0],g[1],g[2],g[3],.025));});s.practice.forEach((q,i)=>{p.html=p.html.replace("__PRACTICE_"+i+"__",P(q.q)+paper("Your diagram, reasoning and calculation")+reveal("Explain the marking points","<table class=pf-marking><thead><tr><th>Explained working and reasoning</th><th>Marks</th></tr></thead><tbody>"+q.points.map(x=>"<tr><td>"+esc(x)+"</td><td>1</td></tr>").join("")+"</tbody></table>"));});p.html=p.html.replace("__CHECK__",check(s.id+"-guided-model",s.bank[0].q,s.bank[0].o,s.bank[0].a,s.bank[0].o.map(()=>s.bank[0].explain)));p.html=p.html.replace("__TRANSFER__",paper("Explain with quantities and a model")+reveal("Compare your explanation",P("The LED receivesVfI, whereas the supply also powers resistor heating. Optical output divided by total supply input is consequently lower than device-only efficiency in this series-resistor circuit.")));});C.register(s);}
})();
